// Üretilen dosya: tool/ozgun/uret.py. Sınav Hazırlık · Sözel mantık ve akıl yürütme (sıralama, eşleştirme, koşullu çıkarım; her soru kendi verisini içerir) (orta).
const ozExam4Orta = <(String, String, List<String>, String)>[
  ('Beş çanta tartılıyor. Kırmızı, maviden ağırdır; yeşil, kırmızıdan ağırdır; sarı, maviden hafiftir; mor ise yeşilden hafif ama kırmızıdan ağırdır. Ağırdan hafife dizildiğinde tam ortada hangi renk bulunur?', 'Kırmızı olan', ['Mor olan', 'Mavi renkli olan', 'Yeşil olan'], 'Sıralama yeşil > mor > kırmızı > mavi > sarı biçimindedir. Beş öğenin ortası üçüncü sıradır ve orada kırmızı vardır.'),
  ('Beş kişilik bir koşuda Kerem, Arda\'nın hemen arkasından; Eda ise Kerem\'den iki sıra sonra bitirmiştir. Sude, Arda\'dan önce bitirmiş, Berk ise sonuncu olmamıştır. Yarışı üçüncü sırada kim bitirmiştir?', 'Kerem', ['Berk', 'Arda', 'Eda'], 'Eda, Arda\'dan üç sıra geride olduğundan Arda en çok ikinci olabilir; Sude ondan önce olduğundan Sude 1., Arda 2., Kerem 3., Berk 4., Eda 5. olur.'),
  ('Beş katlı bir apartmanda her katta bir aile oturur: Aksoy, Bilgin, Çelik, Demir ve Er aileleri. Bilginler, Demirlerin hemen üst katındadır; Çelikler en üst kattadır; Aksoylar, Er ailesinden daha alt kattadır; Demirler ise 1. katta oturmaz. Buna göre hangisi kesinlikle doğrudur?', 'Aksoylar 1. katta oturur.', ['Erler 4. katta oturur.', 'Bilginler 3. katta oturur.', 'Demirler 2. katta oturur.'], 'Demirler 2. katta ise Bilginler 3., Aksoylar 1., Erler 4. kattadır; Demirler 3. katta ise Bilginler 4., Aksoylar 1., Erler 2. kattadır. İki durumda da Aksoylar 1. kattadır.'),
  ('Altı katlı bir binada bir dişçi, bir avukat, bir öğretmen, bir aşçı, bir pilot ve bir ressam farklı katlarda oturuyor. Aşçı 1. katta, pilot en üst kattadır. Ressam, avukattan alttadır. Dişçi ile öğretmenin katları arasında tam iki kat bulunur. Avukat kaçıncı katta oturur?', '4. kat', ['2. kat', '3. kat', '5. kat'], '2–5. katlar kalır. Aralarında iki kat olan dişçi ile öğretmen yalnızca 2 ve 5. katlara yerleşebilir; ressam 3., avukat 4. kata düşer.'),
  ('Ece, Cem, Ali, Nur ve Mert bir sinemada yan yana beş koltuğa oturacaktır. Ali tam ortadaki koltukta, Nur en soldadır. Mert, Ali\'nin sağında bir yerdedir. Ece ile Cem yan yana oturmaz. Buna göre hangisi kesinlikle doğrudur?', 'Soldan ikinci koltukta Ece ya da Cem oturur.', ['Mert en sağdaki koltukta, kenarda oturur.', 'Cem, Ali\'nin solunda oturur.', 'Ece, Nur\'un hemen yanında oturur.'], 'Soldan ikinci koltuğa Mert gelemez çünkü Mert Ali\'nin sağındadır; bu yüzden orası Ece ya da Cem\'e kalır. Kalan kişinin hangisinin nerede olduğu ise kesin değildir.'),
  ('Bir rafta soldan sağa beş kitap dizilidir: tarih, kimya, roman, şiir ve atlas. Roman, şiirin hemen solundadır; atlas en sağdadır; tarih, kimyanın sağındadır; kimya en solda değildir. Soldan üçüncü kitap hangisidir?', 'Kimya kitabı', ['Tarih kitabı', 'Şiir kitabı', 'Roman kitabı'], 'Roman-şiir ikilisi 1-2\'de olmazsa kimya ve tarih koşulları sağlanamaz. Böylece roman 1., şiir 2., kimya 3., tarih 4., atlas 5. olur.'),
  ('Bir kursta pazartesiden cumaya kadar her gün tek bir etkinlik yapılır: resim, müzik, satranç, dans ve yüzme. Satranç çarşambadır. Dans, müziğin ertesi günüdür. Yüzme pazartesiye denk gelmez ve resimden önceki bir gündedir. Perşembe günü hangi etkinlik yapılır?', 'Yüzme', ['Resim', 'Dans', 'Müzik'], 'Müzik-dans ikilisi perşembe-cuma olursa yüzme pazartesi olmak zorunda kalır, bu yasaktır. O hâlde müzik pazartesi, dans salı; yüzme perşembe, resim cumadır.'),
  ('Can, Gül ve Efe; İzmir, Van ve Rize\'de yaşıyor, arabaları da beyaz, siyah ve gridir (her biri farklı). Rize\'de yaşayanın arabası gridir. Can Van\'da yaşamaz ve arabası siyahtır. Gül İzmir\'de yaşamaz. Efe\'nin arabası beyaz değildir. Buna göre hangisi doğrudur?', 'Gül\'ün arabası beyazdır.', ['Efe İzmir\'de yaşar.', 'Can\'ın arabasının rengi gridir.', 'Gül Rize\'de yaşar.'], 'Efe beyaz olamaz, siyah da Can\'ındır; Efe\'nin arabası gri, dolayısıyla Efe Rizelidir. Can Van\'da yaşamadığından İzmir\'dedir; Gül Van\'da yaşar ve arabası beyazdır.'),
  ('Beş öğrencinin sınav puanları birbirinden farklıdır. Arda\'nın puanı Eda\'dan yüksek, Mert\'ten düşüktür. Sude, Mert\'ten daha yüksek puan almıştır. Cem\'in puanı ise Arda\'nınkinden düşüktür. Aşağıdaki ikililerden hangisinin puan sıralaması kesin olarak bilinemez?', 'Cem ile Eda', ['Sude ile Arda', 'Mert ile Eda', 'Cem ile Mert'], 'Sude > Mert > Arda kesindir; Eda ve Cem ise Arda\'nın altındadır ama ikisi arasında bir bilgi verilmemiştir.'),
  ('Bir sırada yan yana oturan öğrencilerden Can soldan yedinci, Oya sağdan dördüncüdür. Can, Oya\'nın solundadır ve ikisinin arasında iki öğrenci vardır. Sırada kaç öğrenci oturmaktadır?', '13', ['11', '12', '14'], 'Can\'a kadar 7 kişi, aradaki 2 kişi ve Oya dâhil sağdan 4 kişi vardır: 7 + 2 + 4 = 13.'),
  ('“Yağmur yağarsa yollar ıslanır.” bilgisi doğrudur. Sabah sokağa çıkan Elif yolların ıslak olduğunu görmüştür. Buna göre hangisi söylenebilir?', 'Yağmurun yağıp yağmadığı kesin bilinemez.', ['Gece kesinlikle yağmur yağmıştır.', 'Gece kesinlikle hiç yağmur yağmamış olmalıdır.', 'Yollar gün boyu ıslak kalacaktır.'], 'Yollar başka nedenlerle de (örneğin yıkanarak) ıslanmış olabilir. Sonucun gerçekleşmesi koşulun gerçekleştiğini kanıtlamaz.'),
  ('Bir mağaza, 500 liranın üzerindeki alışverişlerde kargo ücreti almadığını duyurmuştur. Başka bir kargo kuralı açıklanmamıştır. Selin bu mağazadan 400 liralık alışveriş yapmıştır. Selin\'in kargo ücreti hakkında hangisi doğrudur?', 'Kargo ücreti ödeyip ödemeyeceği kesin değildir.', ['Kesinlikle kargo ücreti ödeyecektir.', 'Kesinlikle ücretsiz kargo hakkından yararlanacaktır.', 'Kargo ücreti 100 lira olacaktır.'], 'Duyuru yalnızca 500 lira üstünü kapsar; daha düşük tutarlar için ne söylendiği bilinmez. Koşulun sağlanmaması sonucun gerçekleşmeyeceğini göstermez.'),
  ('“Bir canlı memeliyse omurgalıdır.” önermesiyle mantıksal olarak denk olan önerme hangisidir?', 'Omurgalı olmayan bir canlı memeli değildir.', ['Omurgalı olan her canlı memelidir.', 'Memeli olmayan hiçbir canlı omurgalı değildir.', 'Bazı memeliler omurgasız olabilir.'], '“p ise q” önermesi, karşıt tersi olan “q değilse p değildir” ile denktir. Diğer seçenekler önermenin tersi ya da çelişiğidir.'),
  ('Bir ülkede sürücü belgesi alabilmek için 18 yaşını doldurmuş olmak gerekir ve bu kurala her zaman uyulur. Buna göre hangisi kesinlikle doğrudur?', 'Sürücü belgesi olan herkes 18 yaşını doldurmuştur.', ['18 yaşını dolduran herkes belge alır.', '18 yaşından küçükler de belge alabilir.', 'Belgesi olmayan herkesin 18 yaşından küçük olduğu anlaşılır.'], 'Yaş koşulu gereklidir ama yeterli değildir. Belge sahibi olan herkes bu koşulu sağlamıştır; koşulu sağlayan herkesin belge aldığı ise söylenemez.'),
  ('Bir bilgi yarışmasında yarışmacı ancak ve ancak tüm soruları doğru yanıtlarsa büyük ödülü kazanır. Deniz büyük ödülü kazanamamıştır. Buna göre hangisi kesinlikle doğrudur?', 'Deniz en az bir soruyu yanlış ya da boş bırakmıştır.', ['Deniz hiçbir soruya doğru yanıt verememiş olmalıdır.', 'Deniz bütün soruları doğru yanıtlamıştır.', 'Deniz yarışmaya hiç katılmamıştır.'], '“Ancak ve ancak” iki yönlü koşuldur: ödül yoksa tüm soruların doğru yanıtlanması da yoktur. Bu, en az bir sorunun doğru yanıtlanmadığı anlamına gelir.'),
  ('“Bütün öğrenciler sınavı geçti.” önermesinin değillemesi (olumsuzu) aşağıdakilerden hangisidir?', 'En az bir öğrenci sınavı geçemedi.', ['Hiçbir öğrenci sınavı geçemedi.', 'Bazı öğrenciler sınavı geçti.', 'Sınava giren öğrencilerin çoğu sınavı geçemedi.'], '“Bütün ... geçti” yargısını çürütmek için tek bir geçemeyen öğrenci yeterlidir. “Hiçbiri geçemedi” ise daha güçlü bir iddiadır, değilleme değildir.'),
  ('“Bazı kediler siyahtır.” önermesinin değillemesi aşağıdakilerden hangisidir?', 'Hiçbir kedi siyah değildir.', ['Bazı kediler siyah değildir.', 'Bütün kediler siyahtır.', 'Kedilerin çoğu siyah değildir.'], '“Bazı” en az bir anlamına gelir; bunun olumsuzu tek bir siyah kedi bile olmamasıdır.'),
  ('“Hava güneşli olursa pikniğe gideriz.” sözünün yanlış (tutulmamış) sayılacağı tek durum hangisidir?', 'Hava güneşli olmuş ama pikniğe gidilmemiştir.', ['Hava yağmurlu olmuş ve pikniğe gidilmiştir.', 'Hava yağmurlu olmuş ve kimse pikniğe gitmemiştir.', 'Hava güneşli olmuş ve pikniğe gidilmiştir.'], 'Koşullu bir söz yalnızca koşul gerçekleştiği hâlde sonuç gerçekleşmezse çiğnenmiş olur. Hava güneşli değilken ne yapıldığı sözü bozmaz.'),
  ('“Ahmet hem İngilizce hem Almanca bilir.” cümlesinin yanlış olduğu öğrenilmiştir. Buna göre hangisi kesinlikle doğrudur?', 'Ahmet bu iki dilden en az birini bilmez.', ['Ahmet ne İngilizce ne de Almanca bilir; iki dili de bilmez.', 'Ahmet yalnızca İngilizce bilir.', 'Ahmet yalnızca Almanca bilir.'], '“p ve q” yanlışsa p ile q\'dan en az biri yanlıştır. Hangisinin ya da ikisinin birden yanlış olduğu belirlenemez.'),
  ('Bir evde şu kural geçerlidir: “Elektrik kesilmezse buzdolabındaki yiyecekler bozulmaz.” Akşam eve dönen aile, yiyeceklerin bozulduğunu görmüştür. Bu kurala göre hangisi kesinlikle doğrudur?', 'Gün içinde elektrik kesilmiştir.', ['Buzdolabının motoru gün içinde arızalanmıştır.', 'Elektrik hiç kesilmemiştir.', 'Yiyecekler önceden bozuktu.'], 'Kural “yiyecekler bozulduysa elektrik kesilmiştir” biçiminde de okunabilir (karşıt ters). Sonuç gerçekleştiğine göre elektrik kesilmiştir.'),
  ('Bir sınıfta “Yalnızca ödevini bitiren öğrenciler teneffüse çıkabilir.” kuralı vardır. Aşağıdakilerden hangisi bu kuralın çiğnendiğini gösterir?', 'Ödevini bitirmemiş bir öğrenci teneffüse çıkmıştır.', ['Ödevini bitiren bir öğrenci sınıfta kalmıştır.', 'Ödevini bitirmemiş bir öğrenci teneffüste sınıfta kalmıştır.', 'Ödevini bitiren bir öğrenci teneffüse çıkmıştır.'], 'Kural, teneffüse çıkan herkesin ödevini bitirmiş olmasını şart koşar. Ödevini bitirip içeride kalmak kuralı bozmaz.'),
  ('Bir bitkinin çiçek açabilmesi için hem yeterli ışık hem de düzenli su gereklidir. Balkondaki saksıda bulunan bitki çiçek açmıştır. Buna göre hangisi kesinlikle doğrudur?', 'Bitki hem yeterli ışık hem de düzenli su almıştır.', ['Bitki yalnızca düzenli su almıştır.', 'Bitkiye gübre de verilmiştir.', 'Işık ve su alan her bitkinin çiçek açacağı kesindir.'], 'Gerekli koşulların ikisi de çiçek açmanın önkoşuludur; çiçek açtıysa ikisi de sağlanmıştır. Bu koşulların yeterli olduğu ise söylenmemiştir.'),
  ('Bir hastanede bazı doktorların satranç oynadığı biliniyor. Ayrıca satranç oynayan herkesin sabırlı olduğu kabul ediliyor. Buna göre kesin olarak hangisi söylenebilir?', 'Bazı doktorlar sabırlıdır.', ['Bütün doktorlar sabırlıdır.', 'Sabırlı olan herkes doktordur.', 'Satranç oynamayan doktorlar sabırsızdır.'], 'Satranç oynayan doktorlar sabırlı olanlar arasındadır; dolayısıyla en az bir doktor sabırlıdır.'),
  ('“Bütün güller çiçektir.” ve “Bazı çiçekler çabuk solar.” öncülleri veriliyor. Güllerin solmasıyla ilgili hangisi doğrudur?', 'Bu öncüllerden kesin bir yargıya varılamaz.', ['Bazı güller çabuk solar.', 'Hiçbir gül çabuk solmaz; solan çiçekler başka türdendir.', 'Bütün güller çabuk solar.'], 'Çabuk solan çiçekler güllerin dışındaki çiçekler de olabilir. Ortak terim (çiçek) ikinci öncülde yalnızca kısmen ele alındığından gül hakkında sonuç çıkmaz.'),
  ('“Hiçbir balina balık değildir.” ve “Bazı deniz canlıları balinadır.” öncüllerinden hangisi kesinlikle çıkar?', 'Bazı deniz canlıları balık değildir.', ['Bazı deniz canlıları balıktır.', 'Hiçbir deniz canlısının balık olmadığı kesin olarak çıkar.', 'Bütün balıklar deniz canlısıdır.'], 'Balina olan deniz canlıları balık olamaz; bu da en az bazı deniz canlılarının balık olmadığını gösterir.'),
  ('Bir spor kulübünün bütün üyeleri lisanslı sporcudur. Hiçbir futbol hakemi lisanslı sporcu değildir. Buna göre hangisi kesinlikle doğrudur?', 'Hiçbir futbol hakemi bu kulübün üyesi değildir.', ['Bazı hakemler kulübe üyedir.', 'Her lisanslı sporcunun kulübün üyesi olduğu anlaşılır.', 'Kulübe üye olmayanlar hakemdir.'], 'Kulüp üyeleri lisanslı sporcular kümesinin içindedir; hakemler ise bu kümenin tamamen dışındadır. İki kümenin kesişimi boştur.'),
  ('“Bazı öğretmenler yazardır.” ve “Bazı yazarlar şairdir.” öncülleri doğrudur. Öğretmenler ile şairler hakkında hangisi söylenebilir?', 'Aralarındaki ilişki bu bilgilerle belirlenemez.', ['Bazı öğretmenler şairdir.', 'Hiçbir öğretmenin şair olmadığı kesin olarak bilinir.', 'Bütün şairler öğretmendir.'], 'Şair olan yazarlarla öğretmen olan yazarlar aynı kişiler olabilir de olmayabilir de. İki “bazı” öncülünden kesin sonuç çıkmaz.'),
  ('Bir okulda futbol takımındaki herkes atletizm takımında da yer alır. Atletizm takımındaki hiç kimse satranç kulübüne üye değildir. Selim satranç kulübünün üyesidir. Selim hakkında hangisi kesinlikle doğrudur?', 'Selim futbol takımında değildir.', ['Selim atletizm takımındadır.', 'Selim futbol takımındadır.', 'Selim okulda hiçbir spor dalıyla ilgilenmez.'], 'Selim atletizm takımında olamaz; futbol takımındakiler atletizm takımında olduğuna göre futbol takımında da olamaz. Başka spor yapıp yapmadığı bilinmez.'),
  ('Bir dil kursundaki herkes Türkçe bilir. İspanyolca bilenlerin hepsi Fransızca da bilir. Fransızca bilen hiç kimse Rusça bilmez. Bu kursta aşağıdaki kişilerden hangisi bulunamaz?', 'Hem İspanyolca hem de Rusça bilen biri', ['Hem Türkçe hem de Fransızca bilen bir kursiyer', 'Yalnızca Türkçe bilen biri', 'Türkçe ile birlikte Rusça bilen biri'], 'İspanyolca bilen Fransızca da bilir, Fransızca bilen de Rusça bilemez. Bu yüzden İspanyolca ve Rusça bir kişide birleşemez.'),
  ('“Hiçbir vegan et yemez.” önermesine mantıksal olarak denk olan hangisidir?', 'Et yiyen hiç kimse vegan değildir.', ['Et yemeyen herkes vegandır.', 'Bazı veganların ara sıra et yediği söylenebilir.', 'Et yemeyen kimse vegan sayılmaz.'], '“Hiçbir A B değildir” önermesi iki yönlüdür; “Hiçbir B A değildir” ile aynı anlamı taşır.'),
  ('“Bazı ressamlar heykeltıraştır.” önermesi doğruysa aşağıdakilerden hangisi kesinlikle doğrudur?', 'Bazı heykeltıraşlar ressamdır.', ['Bütün ressamlar heykeltıraştır.', 'Bazı ressamlar heykeltıraş değildir.', 'Hiçbir heykeltıraş ressam değildir.'], 'Hem ressam hem heykeltıraş olan en az bir kişi vardır; bu kişi aynı zamanda ressam olan bir heykeltıraştır. Ressamların hepsinin ya da bir kısmının heykeltıraş olmadığı ise bilinemez.'),
  ('Bir ekipteki herkes ya mühendis ya da teknisyendir; kimse ikisi birden değildir. Ekipteki mühendislerin hiçbiri vardiyalı çalışmaz. Ekipten Nil vardiyalı çalışmaktadır. Buna göre Nil hakkında hangisi kesindir?', 'Nil bir teknisyendir.', ['Nil bir mühendistir.', 'Nil hem mühendis hem teknisyendir.', 'Nil ekibin yöneticisidir.'], 'Vardiyalı çalışan biri mühendis olamaz. Ekipte yalnızca iki seçenek bulunduğundan Nil teknisyendir.'),
  ('Bir adada yaşayanlar ya doğrucudur (her zaman doğruyu söyler) ya da yalancıdır (her zaman yalan söyler). Arif, yanındaki Bora\'yı göstererek “İkimiz de yalancıyız.” diyor. Arif ve Bora\'nın türleri nedir?', 'Arif yalancı, Bora doğrucu', ['İkisinin de yalancı olduğu anlaşılır', 'Arif doğrucu, Bora yalancıdır', 'İkisinin de doğrucu olduğu anlaşılır'], 'Arif doğrucu olsaydı kendisini yalancı ilan edemezdi; demek ki Arif yalancıdır. Sözü yanlış olduğundan ikisi birden yalancı değildir, Bora doğrucudur.'),
  ('Bir adada yaşayanlar ya doğrucudur (her zaman doğruyu söyler) ya da yalancıdır (her zaman yalan söyler). Adada yaşayan hiç kimse aşağıdaki cümlelerden hangisini söyleyemez?', '“Ben bir yalancıyım.”', ['“Ben her zaman doğru konuşurum.”', '“Yanımdaki kişi bir yalancıdır.”', '“İkimizden en az biri doğrucudur.”'], 'Doğrucu bu cümleyi söylerse yalan söylemiş, yalancı söylerse doğru söylemiş olur; ikisi de imkânsızdır. Diğer cümleler uygun koşullarda söylenebilir.'),
  ('Evdeki vazoyu Ali, Banu ya da Cem\'den biri kırmıştır. Ali “Ben kırmadım.”, Banu “Vazoyu Cem kırdı.”, Cem “Banu yalan söylüyor.” diyor. Üçünden yalnızca birinin doğru söylediği biliniyorsa vazoyu kim kırmıştır?', 'Ali', ['Banu', 'Cem', 'Kimin kırdığı bilinemez'], 'Banu ile Cem\'in sözlerinden tam biri doğrudur. Bu durumda Ali\'nin sözü yanlış olmalıdır; yani vazoyu Ali kırmıştır. Ali kırdıysa Cem kırmamıştır ve yalnızca Cem doğru söyler.'),
  ('Bir adada yaşayanlar ya doğrucudur (her zaman doğruyu söyler) ya da yalancıdır (her zaman yalan söyler). Atlas “Berk ile ben aynı türdeniz.”, Berk ise “Biz farklı türlerdeniz.” diyor. Buna göre hangisi kesinlikle doğrudur?', 'Berk doğrucudur.', ['Atlas doğrucudur.', 'İkisi aynı türdendir.', 'Berk bir yalancıdır.'], 'İki söz birbirinin tersidir; tam biri doğrudur. İkisi farklı türdedir, öyleyse doğru olan Berk\'in sözüdür ve Berk doğrucudur.'),
  ('Üç kutudan yalnızca birinde altın vardır. Birinci kutuda “Altın bu kutuda.”, ikinci kutuda “Altın bu kutuda değil.”, üçüncü kutuda “Altın birinci kutuda değil.” yazıyor. Bu yazılardan yalnızca biri doğruysa altın hangi kutudadır?', 'İkinci kutuda', ['Birinci kutuda', 'Üçüncü kutuda', 'Belirlemek mümkün olmaz'], 'Birinci ve üçüncü yazılar birbirinin tersidir, doğru olan bunlardan biridir. Öyleyse ikinci yazı yanlıştır ve altın ikinci kutudadır.'),
  ('Bir adada yaşayanlar ya doğrucudur (her zaman doğruyu söyler) ya da yalancıdır (her zaman yalan söyler). Adada rastgele seçilen birine “Sen doğrucu musun?” diye soruluyor. Bu soruya alınacak yanıt için hangisi doğrudur?', 'Herkes “evet” der.', ['Doğrucu “evet”, yalancı “hayır” der.', 'Doğrucu “hayır”, yalancı “evet” der.', 'Herkes yanıt vermekten kaçınır.'], 'Doğrucu doğru olarak “evet” der. Yalancı ise gerçekte doğrucu olmadığı için yalan söyleyerek yine “evet” der. Bu yüzden bu soru kişinin türünü ortaya çıkarmaz.'),
  ('Bir adam elindeki fotoğrafı göstererek “Bu kişinin babası, benim babamın tek oğludur.” diyor. Fotoğraftaki kişi adamın nesidir?', 'Çocuğu', ['Kendisi', 'Babası', 'Kardeşi'], 'Adamın babasının tek oğlu adamın kendisidir. Fotoğraftakinin babası adam olduğuna göre fotoğraftaki kişi adamın çocuğudur.'),
  ('Kaan, Nermin\'in oğludur. Nermin, Oğuz ile Sevim çiftinin tek kızıdır. Sevim, Kaan\'ın nesidir?', 'Anneannesi', ['Babaannesi', 'Annesinin teyzesi', 'Halası'], 'Sevim, Kaan\'ın annesi Nermin\'in annesidir; annenin annesi anneannedir.'),
  ('Bir evde iki anne, iki kız ve bir büyükanne olduğu söyleniyor. Bu ifadeye uyan en az kaç kişi vardır?', '3', ['4', '5', '2'], 'Büyükanne, onun kızı ve torunu yeterlidir: büyükanne ile kızı iki annedir, kızı ile torun iki kızdır.'),
  ('Zeki\'nin tek kardeşi Ayten\'dir. Ayten\'in oğlu Bora ile Zeki\'nin oğlu Can arasındaki akrabalık Can açısından nasıl adlandırılır?', 'Bora, Can\'ın hala oğludur.', ['Bora, Can\'ın amca oğludur.', 'Bora, Can\'ın dayı oğludur.', 'Bora, Can\'ın teyze oğludur.'], 'Ayten, Can\'ın babası Zeki\'nin kız kardeşidir, yani Can\'ın halasıdır. Halanın oğlu hala oğludur.'),
  ('Sabah güneş doğarken açık bir alanda duran Melis\'in gölgesi tam sağ tarafına düşmektedir. Melis hangi yöne bakmaktadır?', 'Güneye', ['Kuzeye', 'Doğuya', 'Güneydoğuya'], 'Güneş doğudan doğar, gölge batıya düşer. Batı Melis\'in sağındaysa Melis güneye bakmaktadır.'),
  ('Kuzeye bakan bir asker önce saat yönünde 90°, ardından saat yönünün tersine 180°, en sonda da saat yönünde 45° dönüyor. Asker artık hangi yöne bakmaktadır?', 'Kuzeybatı', ['Kuzeydoğu', 'Güneybatı', 'Güneydoğu'], 'Kuzeyden saat yönünde 90° doğuya, sonra ters yönde 180° batıya, ardından saat yönünde 45° dönünce batı ile kuzeyin ortası olan kuzeybatıya bakar.'),
  ('Ahmet\'in evi Kemal\'in evinin 1 km doğusunda, Mehmet\'in evi Ahmet\'inkinin 1 km güneyinde, Kemal\'in evi de Hasan\'ın evinin 1 km kuzeyindedir. Hasan\'ın evi Mehmet\'in evine göre hangi yöndedir?', 'Batısında', ['Doğusunda', 'Kuzeyinde', 'Güneybatısında'], 'Kemal\'i merkeze koyarsak Ahmet 1 km doğuda, Mehmet onun 1 km güneyinde, Hasan da Kemal\'in 1 km güneyindedir. Hasan ile Mehmet aynı hizadadır ve Hasan batıda kalır.'),
  ('Dünden önceki gün cuma olduğuna göre yarından sonraki gün haftanın hangi günüdür?', 'Salı', ['Pazartesi', 'Çarşamba', 'Pazar'], 'Dünden önceki gün cuma ise dün cumartesi, bugün pazardır. Yarın pazartesi, yarından sonraki gün salıdır.'),
  ('Üç gün önce perşembe olduğuna göre bugünden on gün sonra haftanın hangi günü olur?', 'Çarşamba', ['Salı', 'Perşembe', 'Pazartesi'], 'Üç gün önce perşembe ise bugün pazardır. On gün, bir hafta artı üç gündür; pazardan üç gün sonrası çarşambadır.'),
  ('Bir ayın birinci günü salıya denk gelmiştir. Aynı ayın yirmi beşinci günü hangi gündür?', 'Cuma', ['Perşembe', 'Cumartesi', 'Çarşamba'], '25. gün, 1. günden 24 gün sonradır. 24 gün üç hafta artı üç gündür; salıdan üç gün sonrası cumadır.'),
  ('Ali, Oya\'dan üç gün önce doğmuştur. Oya da Can\'dan iki gün sonra doğmuştur. Can bir perşembe günü doğduysa Ali haftanın hangi günü doğmuştur?', 'Çarşamba', ['Salı', 'Cumartesi', 'Pazartesi'], 'Oya, perşembeden iki gün sonra yani cumartesi doğmuştur. Ali ondan üç gün önce, çarşamba doğmuştur.'),
  ('Bir şifrede sözcüğün harfleri soldan başlayarak ikişer ikişer yer değiştirir; tek kalan son harf yerinde durur. Örneğin KİTAP sözcüğü İKATP olur. Bu kurala göre MASAL nasıl yazılır?', 'AMASL', ['AMSAL', 'MSAAL', 'LASAM'], 'MA → AM, SA → AS çiftleri yer değiştirir, son harf L yerinde kalır: AM + AS + L = AMASL.'),
  ('Türk alfabesinin 29 harfi (A B C Ç D E F G Ğ H I İ J K L M N O Ö P R S Ş T U Ü V Y Z) kullanılıyor. Her harf alfabedeki sıra numarasıyla yazılıyor (A=1, B=2, …, Z=29). Buna göre 16-1-17-24-1-21 dizisi hangi sözcüğü gösterir?', 'MANTAR', ['MANDAL', 'MANTIK', 'KANTAR'], '16. harf M, 1. A, 17. N, 24. T, 1. A, 21. R\'dir; sözcük MANTAR\'dır.'),
  ('Bir kodlu dilde “kedi süt içer” = “la mo ti”, “köpek su içer” = “ne ti ka”, “kedi su sever” = “ka la ro” olarak yazılmaktadır (sözcük sırası farklı olabilir). Bu dilde “süt sever” nasıl yazılır?', 'mo ro', ['mo ka', 'la ro', 'ti ro'], 'Ortak sözcükler: içer = ti, kedi = la, su = ka. Böylece süt = mo, köpek = ne, sever = ro bulunur.'),
  ('İngiliz alfabesindeki (26 harf) harflerle kurulan A, C, F, J, O, … dizisinde bir sonraki harf hangisidir?', 'U', ['T', 'V', 'S'], 'Harfler arasındaki atlama her adımda bir artar: +2, +3, +4, +5. Sonraki adım +6\'dır; O\'dan altı harf sonra U gelir.'),
  ('Türk alfabesinin 29 harfi (A B C Ç D E F G Ğ H I İ J K L M N O Ö P R S Ş T U Ü V Y Z) kullanılıyor. B, Ç, E, G, H, … dizisinde bir sonraki harf hangisidir?', 'İ', ['I', 'J', 'K'], 'Dizi alfabede birer harf atlayarak ilerler (2., 4., 6., 8., 10. harfler). Sıradaki 12. harf İ\'dir.'),
  ('Bir şifrede yalnızca ünlüler değişir; her ünlü a → e → ı → i → o → ö → u → ü → a sırasında bir sonrakine dönüşür, ünsüzler aynen kalır. Bu şifreyle BULUT sözcüğü nasıl yazılır?', 'BÜLÜT', ['BOLOT', 'BALAT', 'BÖLÖT'], 'U\'dan sonraki ünlü Ü\'dür. B, L ve T değişmediği için sonuç BÜLÜT olur.'),
  ('İngiliz alfabesinde her harf, alfabenin öbür ucundaki eşiyle değiştirilir: A ile Z, B ile Y, C ile X yer değiştirir ve bu böyle sürer. LOVE sözcüğü bu şifreyle nasıl yazılır?', 'OLEV', ['MPWF', 'KNUD', 'EVOL'], 'L 12. harftir, eşi 15. harf O\'dur; O\'nun eşi L, V\'nin eşi E, E\'nin eşi V\'dir.'),
  ('İngiliz alfabesi kullanılarak yazılan Z, A, Y, B, X, C, … dizisinde bir sonraki harf hangisidir?', 'W', ['D', 'V', 'U'], 'Dizi iki iç içe diziden oluşur: tek sıradakiler sondan geriye (Z, Y, X), çift sıradakiler baştan ileri (A, B, C) gider. Sıradaki terim tek sıradadır: W.'),
  ('İngiliz alfabesinin kullanıldığı bir şifrede GEL sözcüğü JHO olarak yazılıyor. Aynı kurala göre KAL sözcüğü nasıl yazılır?', 'NDO', ['MCN', 'NCO', 'LBM'], 'Her harf üç harf ileri kaydırılmıştır (G→J, E→H, L→O). Aynı kuralla K→N, A→D, L→O olur.'),
  ('Bir belediye, otobüs bilet fiyatları düşürülürse şehir merkezindeki trafiğin azalacağını savunuyor. Bu görüş aşağıdaki varsayımlardan hangisine dayanır?', 'Ucuzlayan otobüs, bazı sürücüleri özel aracı bırakmaya yöneltir.', ['Şehirdeki otobüslerin tamamı elektrikle çalışmaktadır.', 'Şehir merkezindeki otopark sayısı sürücülerin ihtiyacını karşılayacak düzeydedir.', 'Bilet fiyatları son yıllarda hiç değişmeden aynı kalmıştır.'], 'Fiyat düşüşünün trafiği azaltması ancak bazı insanların arabasını bırakıp otobüse binmesiyle mümkündür. Diğerleri sonuca ulaşmak için gerekli değildir.'),
  ('“Bu restoran akşamları her zaman dolu oluyor; demek ki yemekleri lezzetlidir.” akıl yürütmesindeki örtük varsayım hangisidir?', 'Müşteriler restoran seçerken lezzeti önemser.', ['Restoranın fiyatları bölgedeki en düşük fiyatlardır.', 'Restoranın aşçısı uzun yıllardır bu işi yapmaktadır.', 'Akşamları şehirde açık olan başka restoran yoktur.'], 'Doluluktan lezzete varabilmek için insanların lezzetli yerleri tercih ettiği kabul edilmelidir. Ucuzluk ya da rakipsizlik ise sonucu zayıflatan başka açıklamalardır.'),
  ('“Murat bu yıl bir sınav kursuna yazıldı; bu yüzden sınavı kesinlikle kazanacak.” yargısı hangi varsayıma dayanmaktadır?', 'Kursa gitmek sınavı kazanmak için yeterlidir.', ['Murat geçen yıl da aynı sınava girmiştir.', 'Murat\'ın yazıldığı kurs şehrin en pahalı kursudur.', 'Sınavı kazanan herkes bir kursa gitmiştir.'], '“Kesinlikle kazanacak” sonucu, kursa gitmenin tek başına başarıyı garanti ettiği kabul edilirse çıkar. “Kazanan herkes kursa gitmiştir.” ifadesi ise kursun gerekli olduğunu söyler, yeterli olduğunu değil.'),
  ('Araştırmacılar, gece geç saate kadar ekrana bakan gençlerin daha az uyuduğunu ve bunun ekranın yaydığı ışıktan kaynaklandığını öne sürüyor. Aşağıdakilerden hangisi bu açıklamayı en çok güçlendirir?', 'Aynı süre ekrana bakıp ışık filtreli gözlük takan gençlerin daha iyi uyuduğu görülmüştür.', ['Gençlerin büyük çoğunluğunun akıllı telefonu olduğu belirlenmiştir.', 'Bazı yetişkinlerin de gece geç saatlere kadar televizyon izlediği uzun süredir bilinmektedir.', 'Uyku süresinin yaşa ve kişiye göre değiştiği uzun zamandır bilinmektedir.'], 'Ekrana bakma süresi aynı tutulup yalnızca ışık engellendiğinde uykunun düzelmesi, nedenin ışık olduğunu doğrudan destekler.'),
  ('Bir okulda kantinde gazlı içecek satışı yasaklandıktan sonra öğrencilerin diş sağlığının düzeldiği görülmüş, müdür bunu yasağa bağlamıştır. Hangisi müdürün açıklamasını en çok zayıflatır?', 'Yasakla aynı dönemde okulda ücretsiz diş taraması ve fırçalama eğitimi başlamıştır.', ['Öğrencilerin çoğu kantinden en çok tost ve ayran satın almaktadır.', 'Okulun bulunduğu ilçede başka okullarda da kantin bulunmaktadır.', 'Yasaktan önce de bazı öğrencilerin dişlerinin sağlıklı olduğu okul hemşiresince biliniyordu.'], 'Aynı dönemde başlayan tarama ve eğitim, düzelmeyi açıklayabilecek başka bir nedendir; bu da düzelmenin yasaktan kaynaklandığı iddiasını zayıflatır.'),
  ('Bir firma, yeni gübresini kullanan çiftçilerin bu yıl %20 daha fazla ürün aldığını belirterek gübrenin etkili olduğunu savunuyor. Hangisi bu savı en çok zayıflatır?', 'Gübreyi kullanmayan çiftçilerin verimi de bu yıl benzer oranda artmıştır.', ['Gübrenin fiyatı rakip ürünlerin fiyatından biraz daha yüksektir.', 'Gübreyi kullanan çiftçilerin bazıları geçen yıl da aynı firmadan ürün almıştır.', 'Firma bu gübreyi geliştirmek için uzun yıllar boyunca araştırma yapmıştır.'], 'Gübre kullanılmayan tarlalarda da aynı artış varsa artışın nedeni gübre değil, o yılın genel koşulları olabilir.'),
  ('Bir kasabada halk kütüphanesi açıldıktan sonra okuma alışkanlığının arttığı ileri sürülüyor. Aşağıdakilerden hangisi bu iddiayı en çok destekler?', 'Açılıştan önce ve sonra yapılan anketlerde kitap okuyan kişi sayısı belirgin biçimde artmıştır.', ['Kütüphane binası kasabanın en eski tarihî yapılarından biri olarak seçilmiştir.', 'Kasabadaki kitapçı dükkânı, kütüphane açılmadan birkaç yıl önce kapanmak zorunda kalmıştır.', 'Kütüphanenin açılış törenine kasabanın bütün okullarından öğrenciler katılmıştır.'], 'İddia bir değişim ileri sürdüğü için öncesi ve sonrasını karşılaştıran ölçüm en güçlü destektir. Kitapçının kapanması ise aksi yönde bir ipucudur.'),
  ('“Bu kitapta yazılanların hepsi doğrudur, çünkü kitabın girişinde içindekilerin doğru olduğu yazıyor.” akıl yürütmesinin kusuru nedir?', 'Kanıtlanacak şey kanıt olarak kullanılmıştır.', ['Karşı tarafın görüşü çarpıtılarak eleştirilmiştir.', 'Konuyla ilgisiz bir uzmanın sözüne dayanılmıştır.', 'Olası seçenekler yapay biçimde ikiye indirilmiştir.'], 'Kitabın doğruluğu yine kitabın kendi ifadesiyle kanıtlanmaya çalışılıyor; bu döngüsel akıl yürütmedir.'),
  ('Bir reklamda ünlü bir futbolcu, bir vitamin ilacının bağışıklığı güçlendirdiğini söylüyor ve bu yüzden ilacın etkili olduğu ileri sürülüyor. Bu çıkarımdaki temel sorun nedir?', 'Görüşüne başvurulan kişi bu konuda uzman değildir.', ['Sorun bilinçli olarak yalnızca iki seçeneğe indirgenmiştir.', 'Karşıt görüşü savunanların kişiliğine saldırılmaktadır.', 'Küçük bir adımın büyük felakete yol açacağı söylenmektedir.'], 'Futbolcunun ünü tıbbi bir iddiayı kanıtlamaz. Bu, yetkeye (otoriteye) yanlış başvurma hatasıdır.'),
  ('A: “Okul günlerinin bir saat kısaltılmasını öneriyorum.” B: “Yani çocukların hiç eğitim almamasını istiyorsun!” B\'nin yanıtında hangi hata vardır?', 'Korkuluk safsatası', ['Aceleci genelleme', 'Döngüsel akıl yürütme', 'Çoğunluğa başvurma'], 'B, A\'nın önerisini çarpıtarak savunulması kolay olmayan aşırı bir görüşe dönüştürüyor ve bu uydurma görüşü eleştiriyor.'),
  ('“Yeni ayakkabılarımı giydiğim gün takımımız maçı kazandı; bu ayakkabılar bize şans getiriyor.” sözündeki hata hangisidir?', 'Ardışıklığı nedensellik sanmak', ['Yetkeye yanlış başvurmak', 'Seçenekleri ikiye indirmek', 'Karşı tarafın kişiliğine saldırmak'], 'İki olayın art arda gelmesi birinin diğerine yol açtığını göstermez. Bu hataya “ardından geldi, öyleyse ondan dolayı” denir.'),
  ('Aşağıdaki akıl yürütmelerden hangisi mantıksal olarak geçerlidir?', 'Bütün metaller ısıyı iletir; bakır bir metaldir; öyleyse bakır ısıyı iletir.', ['Bütün kuşların kanadı vardır; yarasanın da kanadı vardır; öyleyse yarasa bir kuştur.', 'Bazı öğrenciler gözlüklüdür; Ali öğrencidir; öyleyse Ali gözlüklüdür.', 'Yağmur yağarsa yer ıslanır; yağmur yağmadı; öyleyse yer ıslanmadı.'], 'Bakır örneği geçerli bir kıyastır. Yarasa örneği sonucu doğrulama, gözlük örneği “bazı”dan bireye sonuç çıkarma, yağmur örneği ise koşulu inkâr etme hatasıdır.'),
  ('Bir otoparktaki 12 aracın 7\'si beyaz, 8\'i dizel motorludur. Buna göre beyaz ve dizel motorlu araçların sayısı en az kaçtır?', '3', ['1', '4', '7'], 'Beyaz ve dizel araçların toplamı 7 + 8 = 15\'tir ve bu sayı araç sayısını 3 aşar. Bu fazlalık iki özelliği birden taşıyan araçlardan gelir.'),
  ('Bir kulübün 20 üyesinden 12\'si satranç, 15\'i dama oynamaktadır ve her üye bu oyunlardan en az birini oynar. Buna göre aşağıdakilerden hangisi olamaz?', 'İki oyunu birden oynayan 5 kişi vardır.', ['İki oyunu birden oynayan 7 kişi vardır.', 'Yalnızca dama oynayan 8 kişi bulunmaktadır.', 'Yalnızca satranç oynayan 5 kişi bulunmaktadır.'], 'Her üye en az bir oyun oynadığından iki oyunu birden oynayanlar tam 12 + 15 − 20 = 7 kişidir. Böylece yalnızca satranç oynayanlar 5, yalnızca dama oynayanlar 8 kişidir; ortak oyuncu sayısı 5 olamaz.'),
  ('Aslı, Bekir ve Cansu; Türkçe, tarih ve müzik derslerinden birer tanesini pazartesi, salı ve çarşamba günlerinden birinde veriyor. Aslı Türkçe vermez. Müzik dersi salıdır. Bekir\'in dersi pazartesidir. Tarihi Cansu verir ve Cansu\'nun dersi pazartesi değildir. Salı günü dersi kim verir?', 'Aslı', ['Bekir', 'Cansu', 'Belirlenemez'], 'Cansu tarih verdiği için salı (müzik günü) gelemez, pazartesi de değildir; Cansu çarşambadır. Bekir pazartesi olduğuna göre salı Aslı\'ya kalır ve Aslı müzik öğretir.'),
  ('Dört takım (A, B, C, D) birbiriyle birer kez karşılaşmış ve hiçbir maç berabere bitmemiştir. A bütün maçlarını kazanmış, D hiç maç kazanamamış, B de C\'yi yenmiştir. C kaç maç kazanmıştır?', '1', ['0', '2', '3'], 'Her takım üç maç oynar. C, A ve B\'ye kaybetmiş, hiç kazanamayan D\'yi ise yenmiştir. Böylece C\'nin bir galibiyeti vardır.'),
  ('16 takımın katıldığı tek maçlık eleme usulü bir turnuvada her maçı kaybeden takım elenir ve beraberlik olmaz. Şampiyon belli olana kadar toplam kaç maç oynanır?', '15', ['16', '8', '31'], 'Her maç tam bir takımı eler. Şampiyon dışındaki 15 takımın elenmesi gerektiğinden 15 maç oynanır.'),
  ('Bir kulüpte 13 üye bulunmaktadır. Üyelerin doğum tarihleri bilinmediğine göre aşağıdakilerden hangisi kesinlikle doğrudur?', 'En az iki üye aynı ayda doğmuştur.', ['En az iki üye aynı gün doğmuştur.', 'Her ayda doğmuş en az bir üye vardır.', 'En az üç üye aynı ayda doğmuş olmalıdır.'], 'Yılda 12 ay vardır. 13 kişi 12 aya dağıtıldığında en az bir aya iki kişi düşer. Diğer yargılar zorunlu değildir.'),
  ('Bir kutuda 5 sarı, 5 mor ve 5 turuncu kalem vardır. Gözü kapalı biri en az kaç kalem alırsa aynı renkten üç kalemi olduğu garanti edilir?', '7', ['6', '9', '4'], 'En kötü durumda her renkten ikişer kalem, yani 6 kalem alınır. 7. kalem hangi renkten olursa olsun o rengi üçe tamamlar.'),
  ('Bir üniversitede B dersini almak için A\'yı, C dersini almak için hem B\'yi hem D\'yi, E dersini almak için C\'yi önceden geçmek gerekir. Bir öğrenci her dönem en çok iki ders alabiliyorsa ve hiç ders kalmıyorsa E dersini en erken kaçıncı dönemde alabilir?', '4. dönemde', ['3. dönemde', '5. dönemde', '2. dönemde'], 'A → B → C → E zinciri dört dersten oluşur ve her biri bir öncekinden sonraki dönemde alınabilir. D, A ile aynı dönemde alınabildiği için süreyi uzatmaz.'),
  ('Bir öğrenci, bitkilerin gelişiminin ışık miktarına bağlı olduğunu düşünüyor. Özdeş iki fideden birini pencere önüne, diğerini karanlık bir dolaba koyuyor; ikisine de aynı miktarda su veriyor. Bu deneydeki bağımsız değişken hangisidir?', 'Işık alma durumu', ['Fidelerin boyu', 'Verilen su miktarı', 'Saksıların büyüklüğü'], 'Araştırmacının bilerek değiştirdiği etken bağımsız değişkendir; burada bu, ışık koşuludur. Boy ölçülen (bağımlı) değişkendir, su ise sabit tutulmuştur.'),
  ('Bir ilacın etkisini ölçmek için hastalar iki gruba ayrılıyor: bir gruba ilaç, diğerine görünüşü aynı ama etkisiz bir hap veriliyor. Etkisiz hap verilen grubun bulunmasının amacı nedir?', 'İlaç dışındaki etkenlerin etkisini ayırt etmek', ['Hastaların ilaca daha çabuk alışmasını sağlamak', 'İlacın maliyetini olabildiğince düşürmek', 'Deneyi daha az sayıda kişiyle tamamlamak'], 'Kontrol grubu, iyileşmenin ilaçtan mı yoksa beklenti, zaman gibi başka etkenlerden mi kaynaklandığını anlamaya yarar.'),
  ('Aşağıdakilerden hangisi deney ya da gözlemle sınanabilecek bir hipotezdir?', 'Tuzlu su, saf sudan daha düşük sıcaklıkta donar.', ['Evrende hiçbir yolla algılanamayan varlıklar bulunur.', 'Mavi, gökkuşağındaki en güzel renktir.', 'Her şey olması gerektiği biçimde gerçekleşir.'], 'Donma sıcaklığı ölçülebilir ve iddia yanlışsa deneyle gösterilebilir. Diğerleri ya beğeni yargısıdır ya da hiçbir gözlemle sınanamaz.'),
  ('Ali iki gübreyi karşılaştırmak için bir saksıya A gübresi verip güneşe, diğerine B gübresi verip gölgeye koyuyor. Bir ay sonra A gübreli bitkinin daha çok büyüdüğünü görüp A\'nın daha iyi olduğuna karar veriyor. Bu deneyin temel kusuru nedir?', 'Saksılar arasında birden çok koşul farklıdır.', ['Deneyde yalnızca iki gübre denenmiştir.', 'Bitkiler bir aydan uzun süre izlenmemiştir.', 'Saksılara her gün eşit miktarda su verilmiştir.'], 'Gübre ile birlikte ışık da değiştiği için büyüme farkının gübreden mi güneşten mi kaynaklandığı ayırt edilemez.'),
  ('Bir şehirde dondurma satışlarının arttığı aylarda boğulma olaylarının da arttığı görülmüştür. Bu durumun en makul açıklaması hangisidir?', 'Sıcak hava hem dondurma tüketimini hem de denize girmeyi artırır.', ['Dondurma yemek, yüzme sırasında kaslarda kramplara yol açarak boğulmaya neden olur.', 'Boğulma haberleri insanlarda dondurma isteği uyandırır.', 'Dondurma satıcıları genellikle kıyı şeridinde çalışır.'], 'İki olgu birlikte değişiyor diye biri diğerinin nedeni değildir; ikisini de etkileyen üçüncü bir etken (sıcak hava) vardır.'),
  ('Bir araştırmada kahvaltı yapan öğrencilerin notlarının, kahvaltı yapmayanlarınkinden ortalama olarak daha yüksek olduğu bulunmuştur. Bu bulgu tek başına neyi gösterir?', 'İki durum arasında bir ilişki bulunduğunu', ['Kahvaltının notları doğrudan yükselttiğini', 'Yüksek not alan herkesin kahvaltı yaptığını', 'Kahvaltı yapmayanların sınavlarda başarısız olduğunu'], 'Gözleme dayalı bir karşılaştırma ilişkiyi gösterir ama nedenselliği kanıtlamaz. Düzenli bir aile yaşamı gibi başka etkenler ikisini birden etkileyebilir.'),
  ('Biri, hastanede çok zaman geçiren kişilerin genellikle daha hasta olduğunu görüp “Hastaneler insanları hasta ediyor.” sonucuna varıyor. Bu akıl yürütmedeki hata nedir?', 'Neden ile sonucun yeri karıştırılmıştır.', ['Az sayıda örnekten genelleme yapılmıştır.', 'Görüşüne başvurulan kişi uzman değildir.', 'Karşı görüş çarpıtılarak eleştirilmiştir.'], 'İnsanlar hasta oldukları için hastanede vakit geçirir; hastane hastalığın sonucu değil, hastalık hastanede bulunmanın nedenidir.'),
  ('Soldan sağa A, B, C, D, E harfleri yazılı beş kart diziliyor. Önce 1. ve 5. sıradaki kartlar, ardından 2. ve 4. sıradakiler, en sonda da 1. ve 3. sıradakiler yer değiştiriyor. Son durumda ortadaki kartta hangi harf vardır?', 'E', ['C', 'A', 'D'], 'İlk değişimle E B C D A, ikinciyle E D C B A oluşur. Son değişimde 1. ve 3. kartlar yer değiştirince C D E B A dizilir ve ortada E kalır.'),
  ('Bir rafta soldan sağa tarih, fizik, kimya, sanat ve müzik kitapları dizilidir. Önce en soldaki ile en sağdaki kitap yer değiştiriyor, ardından bütün dizi tersine çevriliyor. Son durumda soldan ikinci kitap hangisidir?', 'Sanat', ['Fizik', 'Kimya', 'Müzik'], 'İlk adımda müzik, fizik, kimya, sanat, tarih olur. Dizi ters çevrilince tarih, sanat, kimya, fizik, müzik elde edilir.'),
  ('Bir gişe kuyruğunda baştan sona Ali, Can, Ece ve Nur bekliyor. Her dakika kuyruğun başındaki kişi en sona geçiyor. Altı dakika sonra kuyruğun başında kim bulunur?', 'Ece', ['Ali', 'Can', 'Nur'], 'Dört dakikada kuyruk ilk düzenine döner. Altı dakika, dört dakika artı iki dakika demektir; iki kez kaydırılan kuyrukta başta Ece vardır.'),
  ('Bir bursu almak için not ortalaması en az 80 olmalı ve ayrıca ya aile geliri düşük olmalı ya da kişinin en az üç kardeşi bulunmalıdır. Aslı: ortalama 85, gelir yüksek, 2 kardeş. Barış: ortalama 78, gelir düşük, 4 kardeş. Cenk: ortalama 82, gelir yüksek, 3 kardeş. Derya: ortalama 90, gelir yüksek, 1 kardeş. Bursu kim alır?', 'Cenk', ['Aslı', 'Barış', 'Derya'], 'Barış ortalama koşulunu sağlamaz. Aslı ve Derya\'nın ortalaması yeterli olsa da ne gelirleri düşüktür ne de üç kardeşleri vardır. Cenk\'in ortalaması 80\'in üstündedir ve üç kardeşi vardır.'),
  ('Tohum ile ağaç arasındaki ilişkiye en çok benzeyen ikili hangisidir?', 'Tırtıl – kelebek', ['Yaprak – dal', 'Balta – odun', 'Ağaç – orman'], 'Tohum zamanla ağaca dönüşür; tırtıl da başkalaşım geçirerek kelebeğe dönüşür. Diğerleri parça-bütün, araç-nesne ve öğe-topluluk ilişkileridir.'),
  ('Ali, Banu, Cem, Deniz, Ece ve Fatma arasından üç kişilik bir kurul seçilecektir. Ali ile Banu birlikte seçilemez. Cem seçilirse Deniz de seçilmelidir. Ece seçilmezse Fatma seçilmelidir. Aşağıdakilerden hangisi bu kurul olamaz?', 'Cem, Ece ve Fatma', ['Ali, Deniz ve Ece', 'Banu, Ece ve Fatma', 'Cem, Deniz ve Fatma'], 'Cem\'in bulunduğu kurulda Deniz de olmalıdır; Cem, Ece ve Fatma kurulunda Deniz yoktur. Diğer kurullar üç koşulu da sağlar.'),
  ('Ali, Can, Ece, Nur, Oya ve Umut üçer kişilik iki takıma ayrılacaktır. Ali ile Can aynı takımda olacak, Ece ile Nur farklı takımlara düşecek ve Oya, Ali\'nin takımında yer almayacaktır. Buna göre hangisi kesinlikle doğrudur?', 'Oya ile Umut aynı takımdadır.', ['Ece, Ali\'nin takımında yer alır.', 'Nur, Oya\'nın takımında yer alır.', 'Can ile Umut aynı takımdadır.'], 'Ali\'nin takımında Ali, Can ve Ece ile Nur\'dan biri yer alır; Oya giremediği için diğer takımda olur. Umut\'a da Ali\'nin takımında yer kalmaz, böylece Oya ile aynı takımdadır.'),
  ('Ayla, Bulut, Ceyda ve Doruk tek sıra hâlinde dizilecektir. Ayla en başta olacak, Doruk da Bulut\'un hemen arkasında duracaktır. Bu koşullara uyan kaç farklı diziliş vardır?', '2', ['3', '4', '6'], 'Ayla başta sabittir. Bulut-Doruk ikilisi ya 2-3. ya da 3-4. sıralara yerleşir; Ceyda kalan yeri alır. Böylece iki diziliş vardır.'),
  ('Yuvarlak bir masanın çevresine eşit aralıklarla beş kişi oturmuştur: Arda, Bilge, Cenk, Duygu ve Emel. Arda\'nın iki yanında Bilge ile Cenk oturmaktadır. Duygu, Bilge\'nin yanında değildir. Emel\'in iki yanında kimler oturur?', 'Bilge ile Duygu', ['Arda ile Cenk', 'Cenk ile Duygu', 'Bilge ile Arda'], 'Bilge-Arda-Cenk üçlüsünden sonra kalan iki yerden biri Cenk\'e, diğeri Bilge\'ye bitişiktir. Duygu Bilge\'nin yanına oturamadığı için Cenk\'in yanına geçer; Emel ise Bilge ile Duygu arasında kalır.'),
  ('Boy sıralaması uzundan kısaya Ali, Banu, Cem, Dila biçimindedir. Ağırlıkta ise en ağır kişi Banu\'dur; Dila, Ali\'den ağırdır; Cem de Ali\'den ağırdır. Ağırlıkça en hafif olan kişi boy sıralamasında kaçıncıdır?', 'Birinci', ['İkinci', 'Üçüncü', 'Dördüncü'], 'Banu en ağırdır; Dila ve Cem, Ali\'den ağır olduğundan en hafif kişi Ali\'dir. Ali boyca en uzun, yani birincidir.'),
  ('“Hava güzel olur ve Can\'ın işi erken biterse pikniğe gidilir.” bilgisi doğrudur. Pikniğe gidilmemiştir, oysa Can\'ın işi erken bitmiştir. Buna göre hangisi kesinlikle doğrudur?', 'Hava güzel değildir.', ['Hava güzeldir ama Can yorgundur.', 'Can\'ın işi erken bitmemiştir.', 'Pikniğe başka bir gün gidilmiştir.'], 'Piknik yapılmadığına göre iki koşuldan en az biri sağlanmamıştır. Can\'ın işi bittiğine göre sağlanmayan koşul havanın güzel olmasıdır.'),
  ('Bu gece Mert ya da Nil nöbet tutacaktır; ikisi birden tutmayacaktır. Mert nöbet tutarsa Okan izin alır. Okan izin almamıştır. Buna göre bu gece kim nöbet tutar?', 'Nil', ['Mert', 'Okan', 'Mert ile Nil birlikte'], 'Okan izin almadığına göre Mert nöbet tutmuyordur (geriye çıkarım). Seçeneklerden biri kesin olduğu için nöbet Nil\'dedir.'),
  ('“Yalnızca kayıtlı üyeler oy kullanabilir.” ifadesiyle aynı anlamı taşıyan cümle hangisidir?', 'Oy kullanan herkes kayıtlı bir üyedir.', ['Kayıtlı olan her üye mutlaka oy kullanır.', 'Kayıtsız kişilerin bir kısmı da oy kullanabilir.', 'Oy kullanmayan herkesin kayıtsız olduğu anlaşılır.'], '“Yalnızca A, B yapabilir” demek “B yapan herkes A\'dır” demektir. Kayıtlı olmak oy kullanmanın gerekli koşuludur, yeterli koşulu değil.'),
  ('Bir doğum gününde şu iki bilgi doğrudur: Ali gelirse parti uzar. Banu gelirse de parti uzar. Parti uzamamıştır. Buna göre hangisi kesinlikle doğrudur?', 'Ali de Banu da partiye gelmemiştir.', ['Ali gelmiş, Banu ise gelmemiştir.', 'Yalnızca Banu partiye gelmiştir.', 'İkisinden en az biri partiye gelmiştir.'], 'Parti uzamadığına göre iki koşulun hiçbiri gerçekleşmemiştir. Her birine ayrı ayrı geriye çıkarım uygulanır.'),
  ('Deniz “Yarın ya trenle ya da otobüsle gideceğim; ikisini birden de kullanabilirim.” demiştir. Ertesi gün bu sözün yanlış çıktığı anlaşılmıştır. Deniz ne yapmıştır?', 'Ne trenle ne de otobüsle gitmiştir.', ['Yalnızca trenle gitmiştir.', 'Hem trenle hem de otobüsle gitmiştir.', 'Yalnızca otobüsle yolculuk yapmıştır.'], '“A veya B” sözü ancak ikisi de gerçekleşmezse yanlış olur. İki aracı birlikte kullanmak bile sözü doğru yapar.'),
  ('“Kedi miyavlıyorsa açtır.” kuralının doğru olduğu kabul ediliyor. Buna göre aşağıdaki çıkarımlardan hangisi geçersizdir?', 'Kedi aç olduğuna göre miyavlamıştır.', ['Kedi miyavladığına göre açtır.', 'Kedi tok olduğuna göre miyavlamamıştır.', 'Kedi miyavladıysa tok olamaz.'], 'Kural miyavlamanın açlığı gösterdiğini söyler, açlığın miyavlamayı gerektirdiğini söylemez. Aç bir kedi sessiz de durabilir.'),
  ('Bir maratonu bitirmek için düzenli antrenman şarttır. Düzenli antrenman yapan herkes de sağlık raporu almıştır. Zehra bu maratonu bitirmiştir. Buna göre hangisi kesinlikle doğrudur?', 'Zehra sağlık raporu almıştır.', ['Zehra maratonu ilk üçte bitirmiştir.', 'Sağlık raporu alan herkes maratonu bitirir.', 'Zehra\'nın antrenmanları yetersiz kalmıştır.'], 'Maratonu bitirmesi düzenli antrenman yaptığını, düzenli antrenman yapması da sağlık raporu aldığını gösterir.'),
  ('Dolapta ya kek ya kurabiye ya da börek vardır; yalnızca biri bulunur. Dolapta kek yoktur. Börek varsa çay demlenir. Bugün çay demlenmemiştir. Dolapta ne vardır?', 'Kurabiye vardır.', ['Kek vardır.', 'Börek vardır.', 'Hem kek hem börek vardır.'], 'Çay demlenmediğine göre börek yoktur. Kek de olmadığına göre dolapta kurabiye vardır.'),
  ('Bir koridor lambası, iki anahtardan tam biri açıkken yanar; ikisi de açık ya da ikisi de kapalıyken söner. Başlangıçta iki anahtar da kapalıdır. Ali birinci anahtara üç kez, Banu ikinci anahtara iki kez basıyor. Son durumda lamba için ne söylenebilir?', 'Lamba yanar.', ['Lamba söner.', 'Lamba yanıp söner, durumu belirsizdir.', 'Lamba ancak üçüncü basışta yanar.'], 'Üç kez basılan birinci anahtar açık, iki kez basılan ikinci anahtar kapalı kalır. Tam bir anahtar açık olduğu için lamba yanar.'),
  ('Ayla, Bahar ve Ceren kız kardeştir; yaşları 8, 10 ve 12\'dir. En sevdikleri renkler kırmızı, mavi ve yeşildir. En büyük kardeş maviyi sever. Bahar en küçük değildir ve yeşili sevmez. Ceren kırmızıyı sever. Ayla, Ceren\'den büyüktür. Yeşili seven kardeş kaç yaşındadır?', '10', ['8', '12', 'Belirlenemez'], 'Ceren kırmızıcı olduğu için en büyük olamaz. Bahar yeşili sevmediğine göre maviyi sever ve 12 yaşındadır. Yeşil Ayla\'nındır; Ayla, Ceren\'den büyük olduğu için 10 yaşındadır.'),
  ('Tuna, Umut ve Veli bir pastanede çay, kahve ve süt içeceklerinden ve baklava, kek ve tulumba tatlılarından farklı birer tane seçiyor. Tuna çay içmez. Kahve içen baklava yer. Umut tulumba yer. Veli süt içmez. Tuna baklava yemez. Tuna ne içmiştir?', 'Süt', ['Çay', 'Kahve', 'Kesin olarak belirlenemez'], 'Kahveyi içen baklava yer; Tuna baklava, Umut ise tulumba yediği için kahve Veli\'nindir. Tuna çay da içmediğine göre süt içer.'),
  ('“Hiçbir oyuncu maçta sakatlanmadı.” önermesinin değillemesi aşağıdakilerden hangisidir?', 'En az bir oyuncu maçta sakatlandı.', ['Bütün oyuncular maçta sakatlandı.', 'Bazı oyuncular maçta hiç sakatlanmadan oynadı.', 'Oyuncuların çoğu maçta sakatlandı.'], '“Hiçbiri” yargısı tek bir sakatlanan oyuncuyla çürür. Bu yüzden değillemesi “en az bir oyuncu sakatlandı” olur.'),
  ('“Bazı kitaplar ilginç değildir.” önermesinin değillemesi hangisidir?', 'Bütün kitaplar ilginçtir.', ['Bazı kitaplar ilginçtir.', 'Hiçbir kitap ilginç değildir.', 'Kitapların çoğu ilginçtir.'], '“İlginç olmayan en az bir kitap vardır.” önermesinin olumsuzu, ilginç olmayan hiçbir kitap bulunmaması, yani bütün kitapların ilginç olmasıdır.'),
  ('Şu öncüller veriliyor: “Bütün blipler zarptır.”, “Bütün zarplar tıkırdır.” ve “Hiçbir tıkır mor değildir.” Buna göre hangisi kesinlikle doğrudur?', 'Hiçbir blip mor değildir.', ['Bazı blipler mordur.', 'Bütün tıkırlar bliptir.', 'Mor olmayan her şey zarptır.'], 'Blipler zarpların, zarplar da tıkırların içindedir. Tıkırların hiçbiri mor olmadığına göre blipler de mor olamaz.'),
  ('Bir sınıfta yalnızca gözlüklü öğrenciler ön sırada oturur. Ön sırada oturanların hepsi teneffüste kitap okur. Buna göre hangisi kesinlikle doğrudur?', 'Ön sırada gözlüksüz öğrenci yoktur.', ['Her gözlüklü öğrenci ön sırada oturur.', 'Kitap okuyanların tümü ön sırada oturur.', 'Gözlüksüz öğrenciler teneffüste kitap okumaz.'], '“Yalnızca gözlüklüler ön sırada oturur” demek ön sıradaki herkesin gözlüklü olması demektir. Gözlüklülerin hepsinin ön sırada olduğu ise söylenmemiştir.'),
  ('Aşağıdaki önerme çiftlerinden hangisinin iki önermesi birlikte doğru olamaz?', '“Bütün kuşlar uçar.” – “Bazı kuşlar uçmaz.”', ['“Bazı kuşlar uçar.” – “Bazı kuşlar uçmaz.”', '“Hiçbir balık uçmaz.” – “Bazı kuşlar uçar.”', '“Bütün kuşlar yumurtlar.” – “Bazı yumurtlayanlar uçmaz.”'], '“Bütün A, B\'dir.” ile “Bazı A, B değildir.” çelişik önermelerdir; biri doğruysa öteki yanlıştır. Diğer çiftler aynı anda doğru olabilir.'),
  ('Bütün kareler dikdörtgendir. Bütün dikdörtgenler paralelkenardır. Bazı paralelkenarlar kare değildir. Bu üç öncülden kesin olarak hangisi çıkar?', 'Bütün kareler paralelkenardır.', ['Bütün paralelkenarlar dikdörtgendir.', 'Bazı dikdörtgenler kare değildir.', 'Hiçbir paralelkenar kare değildir.'], 'Kareler dikdörtgenlerin, dikdörtgenler paralelkenarların içinde olduğundan kareler paralelkenardır. Kare olmayan paralelkenarların dikdörtgen olup olmadığı ise öncüllerden çıkmaz.'),
  ('Bir kırtasiyeden kalem çalan kişi Akın, Berk ve Ceyhun\'dan biridir. Suçlu yalan söylemekte, suçsuz olanlar doğruyu söylemektedir. Akın: “Berk suçlu değil.” Berk: “Kalemi Ceyhun aldı.” Ceyhun: “Ben suçlu değilim.” Kalemi kim almıştır?', 'Ceyhun almıştır.', ['Akın almıştır.', 'Berk almıştır.', 'Kimin aldığı bilinemez.'], 'Ceyhun suçluysa Akın ile Berk doğru, Ceyhun yalan söylemiş olur; tutarlıdır. Akın ya da Berk suçlu kabul edildiğinde suçsuzlardan birinin yalan söylemesi gerekir.'),
  ('Bir adada yaşayanlar ya doğrucudur (her zaman doğruyu söyler) ya da yalancıdır (her zaman yalan söyler). Emir, Fulya\'yı göstererek “İkimizden en az biri yalancıdır.” diyor. Buna göre Emir ve Fulya\'nın türleri nedir?', 'Emir doğrucu, Fulya yalancı', ['İkisinin de yalancı olduğu anlaşılır', 'Emir yalancı, Fulya doğrucudur', 'İkisinin de doğrucu olduğu anlaşılır'], 'Emir yalancı olsaydı “en az biri yalancı” sözü doğru olurdu; çelişki. Emir doğrucudur, sözü doğrudur; yalancı olan Fulya\'dır.'),
  ('Bir adada yaşayanlar ya doğrucudur (her zaman doğruyu söyler) ya da yalancıdır (her zaman yalan söyler). Beş kişi bir sıra hâlinde duruyor. Sonuncu dışındaki herkes “Hemen arkamdaki kişi yalancıdır.” diyor. En sondaki kişinin doğrucu olduğu biliniyorsa sırada kaç doğrucu vardır?', '3', ['2', '4', '1'], 'Sondaki doğrucu olduğundan önündeki kişinin sözü yanlıştır, yani o yalancıdır. Bu şekilde geriye doğru doğrucu ve yalancılar sırayla gelir: 1., 3. ve 5. kişiler doğrucudur.'),
  ('Selim\'in annesi, Burcu\'nun babasının tek kız kardeşidir. Buna göre Burcu, Selim\'in nesi olur?', 'Dayı kızı', ['Amca kızı', 'Hala kızı', 'Teyze kızı'], 'Selim\'in annesinin erkek kardeşi Burcu\'nun babasıdır; bu kişi Selim\'in dayısıdır. Burcu da dayısının kızıdır.'),
  ('Ahmet, Bülent\'in babasıdır. Bülent, Cengiz\'in babasıdır. Cengiz de Doruk\'un babasıdır. Doruk, Ahmet\'in nesidir?', 'Torununun oğlu', ['Torunu', 'Yeğeninin oğlu', 'Oğlunun kardeşi'], 'Ahmet\'in oğlu Bülent, torunu Cengiz\'dir. Doruk, Cengiz\'in oğlu olduğuna göre Ahmet\'in torununun oğludur.'),
  ('Kuzeye bakan bir robot şu komutları sırayla uyguluyor: 2 adım ileri, sağa dön, 3 adım ileri, sağa dön, 2 adım ileri, sola dön, 1 adım ileri. Robot başladığı noktaya göre nerededir?', '4 adım doğusunda', ['3 adım doğusunda', '4 adım batısında', '2 adım kuzeyinde, 3 adım doğusunda'], 'Kuzeye 2 adım, doğuya 3 adım, güneye 2 adım gider ve kuzey-güney farkı sıfırlanır. Sola dönünce yine doğuya bakar ve 1 adım daha ilerler: toplam 4 adım doğu.'),
  ('Okul, Ayşe\'nin evinin batısındadır. Park, okulun tam güneyindedir. Market, parkın doğusunda ve aynı zamanda evin tam güneyindedir. Park, eve göre hangi yöndedir?', 'Güneybatısında', ['Güneydoğusunda', 'Evin tam güneyinde', 'Kuzeybatısında'], 'Market evin tam güneyinde ve parkın doğusunda olduğuna göre park, evin güneyinde ve batı tarafındadır.'),
  ('Bir ayın 13. günü cumaya denk gelmiştir. Aynı ayın ilk pazartesi günü ayın kaçıdır?', '2', ['6', '3', '9'], '13 cuma ise 9 pazartesidir. Bir hafta geri gidilince 2 de pazartesi olur ve bu ayın ilk pazartesisidir.'),
  ('2023 yılının 1 Şubat günü çarşambaya denk gelmiştir ve o yıl şubat 28 gündür. 2023 yılında şubatın son günü haftanın hangi günüdür?', 'Salı', ['Pazartesi', 'Perşembe', 'Cuma'], '28 Şubat, 1 Şubat\'tan 27 gün sonradır. 27 gün üç hafta artı altı gündür; çarşambadan altı gün sonrası salıdır.'),
  ('Bir öğrenci her üç günde bir yüzmeye gidiyor; ilk kez bir pazartesi gitmiştir. Beşinci kez yüzmeye gittiği gün haftanın hangi günüdür?', 'Cumartesi', ['Cuma', 'Pazar', 'Salı'], 'Beşinci gidiş, ilkinden 4 × 3 = 12 gün sonradır. 12 gün bir hafta artı beş gündür; pazartesiden beş gün sonra cumartesidir.'),
  ('31 gün çeken bir ayın ilk günü pazara denk gelmiştir. Bu ayda kaç tane pazar günü vardır?', '5', ['4', '6', '3'], 'Pazarlar ayın 1, 8, 15, 22 ve 29. günleridir. 36. gün olmadığı için beş pazar vardır.'),
  ('29 harfli Türk alfabesinden belli bir kurala göre seçilen harfler şöyle sıralanmıştır: A, Ç, F, H. Aynı kural sürdürülürse beşinci harf ne olur?', 'J', ['İ', 'I', 'K'], 'Harfler alfabede ikişer harf atlanarak seçilmiştir: 1., 4., 7., 10. harfler. Sıradaki 13. harf J\'dir.'),
  ('İngiliz alfabesinin kullanıldığı bir şifrede her harf, sözcükteki sırası kadar ileri kaydırılıyor: birinci harf 1, ikinci harf 2, üçüncü harf 3 harf ileri gidiyor. Örneğin ABC sözcüğü BDF oluyor. CAT sözcüğü nasıl yazılır?', 'DCW', ['DBU', 'ECV', 'DDW'], 'C bir harf ileri D, A iki harf ileri C, T üç harf ileri W olur.'),
  ('İngiliz alfabesine göre yazılmış Z, X, U, Q, … dizisinde bir sonraki harf hangisidir?', 'L', ['M', 'N', 'K'], 'Harfler geriye doğru 2, 3, 4 harf atlayarak ilerler. Sıradaki adım 5 harftir; Q\'dan beş harf geri L\'dir.'),
  ('Uydurma bir dilde “evler” sözcüğü “tumki”, “ev” sözcüğü “tum”, “kediler” sözcüğü ise “sanki” biçiminde söylenmektedir. Bu dilde “kedi” sözcüğü nasıl söylenir?', 'san', ['tum', 'ki', 'sanki'], '“ev” = tum ve “evler” = tumki olduğundan “-ler” eki ki ile gösterilir. “kediler” = sanki ise kök olan “kedi” san\'dır.'),
  ('Bir kafeterya müdürü “Menüye vegan yemekler eklersek müşteri sayımız artar.” diyor. Bu öngörü aşağıdaki varsayımlardan hangisine dayanmaktadır?', 'Vegan yemek bulamadığı için gelmeyen kişiler vardır.', ['Kafeteryanın şu anki müşterilerinin çoğu vegandır.', 'Vegan yemekler diğer yemeklerden daha ucuza hazırlanır.', 'Kafeteryanın çevresinde başka hiçbir yemek yeri yoktur.'], 'Müşteri sayısının artması için yeni seçeneğin şu anda gelmeyen birilerini çekmesi gerekir. Mevcut müşterilerin vegan olması ise artış sağlamaz.'),
  ('Bir araştırmacı, deneme aşamasındaki bir ilacın farelerde tansiyonu düşürdüğünü görüp insanlarda da aynı etkiyi göstereceğini ileri sürüyor. Bu çıkarım hangi varsayıma dayanır?', 'Fareler ve insanlar bu ilaca benzer tepki verir.', ['İlaç farelerde hiçbir yan etki göstermemiştir.', 'İlacın üretimi oldukça düşük maliyetlidir.', 'Tansiyon sorunu yalnızca ileri yaştaki insanlarda ortaya çıkar.'], 'Hayvan deneyinden insana genelleme yapılırken iki türün ilgili bakımdan benzer olduğu varsayılır.'),
  ('Bir firma, dergi okurlarıyla yaptığı ankette katılımcıların %90\'ının yeni ürünü beğendiğini belirterek “Halk ürünümüzü çok beğeniyor.” sonucuna varmıştır. Hangisi bu sonucu en çok zayıflatır?', 'Anket yalnızca firmanın kendi dergisinin abonelerine yapılmıştır.', ['Ankete katılan okurların yaşları birbirinden oldukça farklılık göstermektedir.', 'Ürün piyasaya çıkalı henüz bir yıl bile olmamıştır.', 'Firmanın rakipleri de benzer ürünler satmaktadır.'], 'Firmanın kendi dergisini okuyanlar, firmayı zaten seven kişiler olabilir. Bu örneklem halkın genelini temsil etmez.'),
  ('Bir araştırmacı, okul bahçesine ağaç dikilmesinin teneffüste öğrencileri daha sakin yaptığını öne sürüyor. Aşağıdakilerden hangisi bu iddiayı en çok güçlendirir?', 'Ağaç dikilmeyen benzer okullarda aynı dönemde böyle bir değişim görülmemiştir.', ['Dikilen ağaçların çoğu bölgeye özgü türlerden seçilmiştir.', 'Öğrenciler ağaç dikme etkinliğine büyük bir istekle ve aileleriyle birlikte katılmıştır.', 'Okulun bahçesi ilçedeki en geniş okul bahçelerinden biridir.'], 'Karşılaştırma grubunda değişim olmaması, sakinleşmenin genel bir eğilimden değil ağaçlardan kaynaklandığını destekler.'),
  ('Bir gişe kuyruğunda Ali\'nin önünde 4 kişi, Banu\'nun arkasında 6 kişi vardır. Ali, Banu\'nun hemen arkasında durduğuna göre kuyrukta toplam kaç kişi vardır?', '10', ['11', '12', '9'], 'Ali 5. sıradadır, Banu da hemen önünde 4. sıradadır. Banu\'nun arkasındaki 6 kişiyle birlikte toplam 4 + 6 = 10 kişi olur.'),
  ('Pelin, Kaan, Ece, Tuna ve Umut yan yana beş sandalyeye oturuyor. Pelin, Kaan\'ın iki sandalye solundadır. Kaan, Ece\'nin hemen solundadır. Ece de Tuna da en sağdaki sandalyede değildir. Soldan ikinci sandalyede kim oturur?', 'Tuna', ['Umut', 'Kaan', 'Pelin'], 'Ece en sağda olmadığına göre Kaan en çok üçüncü sandalyededir; Pelin ondan iki sol olduğundan Pelin 1., Kaan 3., Ece 4. olur. En sağa Tuna oturamadığı için Umut 5., Tuna 2. sandalyededir.'),
  ('Bir yarışmanın ilk turunda 60 puanın altında kalanlar elenir. İkinci tura geçenler, iki jüri üyesinden en az birinden “evet” alırsa finale kalır. Aylin ilk turda 72 puan almış, iki jüriden de “hayır” almıştır. Barış 58 puan almış, iki jüriden de “evet” almıştır. Ceyda 65 puan almış, bir jüriden “evet” almıştır. Finale kim kalır?', 'Ceyda', ['Aylin', 'Barış', 'Aylin ile Ceyda'], 'Barış ilk turda elenir; ikinci turdaki “evet”ler ona yaramaz. Aylin ikinci tura geçse de hiç “evet” almamıştır. Ceyda iki aşamayı da geçer.'),
  ('Bir okulun kıyafet kuralına göre pazartesi ve cuma günleri spor kıyafeti, diğer günler okul forması giyilir; ancak tören olan günlerde hangi gün olursa olsun okul forması giyilir. Bir cuma günü okulda tören yapılacaktır. Öğrenciler o gün ne giymelidir?', 'Forma', ['Spor kıyafeti', 'İstedikleri kıyafet', 'Günlük kıyafet'], 'Tören kuralı bütün günler için geçerli olan bir istisnadır ve cuma kuralından önce gelir; bu yüzden forma giyilir.'),
  ('Bir laboratuvarda içeri girerken koruyucu gözlük ve önlük takmak zorunludur; eldiven ise yalnızca asitle çalışırken zorunludur. Aşağıdaki öğrencilerden hangisi kurala uymamaktadır?', 'Gözlüklü, önlüksüz ve eldivenli olarak tuz çözeltisi hazırlayan', ['Gözlüklü, önlüklü ve eldivensiz olarak su ısıtan', 'Gözlüklü, önlüklü ve eldivenli olarak seyreltik asitle deney yapan', 'Gözlüklü, önlüklü ve eldivenli olarak tartım yapan'], 'Önlük her durumda zorunludur; önlüksüz çalışan öğrenci kuralı çiğner. Asit kullanmayan biri için eldiven takmak ya da takmamak serbesttir.'),
  ('Çamaşır makinesi 60 dakikada yıkıyor; yıkanan çamaşırlar ardından kurutma makinesinde 40 dakika kalıyor. Bulaşık makinesi ise 50 dakika çalışıyor. Bütün makineler aynı anda çalışabiliyorsa, çamaşırların kuruması ve bulaşıkların yıkanması en erken kaç dakikada tamamlanır?', '100 dakikada', ['150 dakikada', '110 dakikada', '60 dakikada'], 'Kurutma ancak yıkama bittikten sonra başlayabilir: 60 + 40 = 100 dakika. Bulaşık makinesi bu sırada paralel çalışıp 50. dakikada biter.'),
  ('“Sıcaklık arttıkça şeker suda daha hızlı çözünür.” hipotezini sınamak için aşağıdaki deneylerden hangisi en uygundur?', 'Eşit şeker, eşit miktarda ama farklı sıcaklıktaki sulara atılıp çözünme süreleri ölçülür.', ['Farklı miktarlarda şeker, farklı sıcaklıktaki ve farklı miktardaki sulara atılıp sonuçlar karşılaştırılır.', 'Aynı sıcaklıktaki suya farklı miktarlarda şeker atılarak tadına bakılır.', 'Şeker ile tuz aynı sıcaklıktaki suya atılıp hangisinin önce çözüneceği izlenir.'], 'Yalnızca sıcaklık değiştirilip şeker ve su miktarı sabit tutulursa süre farkı sıcaklığa bağlanabilir.'),
  ('Bir öğrenci farklı müzik türlerinin bitkilerin büyümesine etkisini araştırıyor. Sonucun güvenilir olması için aşağıdakilerden hangisi bütün bitkilerde aynı tutulmalıdır?', 'Bitkilerin aldığı ışık ve su miktarı', ['Bitkilerin dinlediği müzik türü', 'Deney sonunda ölçülen bitkilerin boy uzunluğu', 'Her bitkinin büyüme hızı'], 'Müzik türü değiştirilen, boy ölçülen değişkendir. Işık ve su gibi diğer etkenler sabit tutulmazsa farkın müzikten kaynaklandığı söylenemez.'),
  ('Bir deneyde aynı türden tohumlar, diğer bütün koşullar aynı tutularak 20 °C\'de 5 günde, 30 °C\'de 3 günde çimlenmiştir. Bu sonuçtan kesin olarak hangisi çıkarılabilir?', 'Bu tohumlarda 30 °C çimlenmeyi hızlandırmıştır.', ['Bütün tohum türleri sıcakta daha hızlı çimlenir.', 'Bu tohumlar 40 °C\'de bir günde çimlenir.', 'Işık tohumların çimlenmesini hiç etkilemez.'], 'Deney yalnızca bu tür ve bu iki sıcaklık hakkında bilgi verir. Başka türlere ya da denenmemiş sıcaklıklara genelleme yapılamaz.'),
  ('Bir araştırmada ülkelerin kişi başına çikolata tüketimi ile aldıkları Nobel ödülü sayısı arasında olumlu bir ilişki bulunmuştur. Bu bulguyla ilgili en doğru değerlendirme hangisidir?', 'Bu ilişki, çikolatanın başarıyı artırdığını kanıtlamaz.', ['Çikolata tüketimini artıran ülkeler daha çok ödül alır.', 'Nobel ödülü almak çikolata tüketimini kesinlikle artırır.', 'İki değişken arasında hiçbir bağlantı olamaz.'], 'İki değişken birlikte değişebilir; ama bu, birinin diğerine yol açtığını göstermez. Zenginlik gibi ortak bir etken ikisini birden etkileyebilir.'),
  ('Bir maçtaki tek golü Can, Efe ya da Kaan atmıştır. Can “Golü Efe attı.”, Efe “Golü ben atmadım.”, Kaan “Golü ben atmadım.” diyor. Bu üç sözden yalnızca biri doğruysa golü kim atmıştır?', 'Kaan', ['Can', 'Efe', 'Belirlenemez'], 'Can ile Efe\'nin sözleri birbirinin tersidir; tam biri doğrudur. O hâlde Kaan\'ın sözü yanlıştır ve golü Kaan atmıştır.'),
  ('Bir evin köpeği, tanımadığı herkese havlamaktadır. Olay gecesi köpek bahçedeydi ve uyanıktı. Pencere kırılırken köpek hiç havlamamıştır. Buna göre hangisi kesinlikle doğrudur?', 'Pencereyi kıran kişi köpeğin tanıdığı biridir.', ['Pencereyi evdeki bir çocuk kırmıştır.', 'Pencere kendiliğinden kırılmıştır.', 'Köpek o gece bahçede hiç kimseyi görmemiştir.'], 'Köpek tanımadıklarına havladığına göre, havlamaması pencereyi kıranın tanıdık biri olduğunu gösterir. Kişinin kim olduğu ise kesinleşmez.'),
  ('Bir kursta bir haftanın yedi gününe toplam 15 ders dağıtılmıştır ve her güne en az bir ders düşmektedir. Buna göre hangisi kesinlikle doğrudur?', 'En az bir günde en az üç ders vardır.', ['Her günde en az iki ders bulunur.', 'Bir günde en çok üç ders olabilir.', 'Tam olarak bir günde dört ders vardır.'], 'Her güne en çok iki ders verilseydi toplam en fazla 14 olurdu. 15 ders bu sınırı aştığına göre en az bir günde üç ya da daha fazla ders vardır.'),
  ('Bir binanın giriş kapısı kuzeye bakmaktadır. Kapıdan içeri giren biri hemen sağa dönerse hangi yöne doğru yürür?', 'Batıya', ['Doğuya', 'Kuzeye', 'Güneye'], 'Kapı kuzeye baktığı için içeri giren kişi güneye doğru ilerler. Güneye bakan birinin sağı batıdır.'),
  ('Yarınki kutlamaya Ali ile Banu\'dan en az biri gelecektir. Ali gelirse pasta alınacak, Banu gelirse çiçek alınacaktır. Buna göre hangisi kesinlikle doğrudur?', 'Pasta ile çiçekten en az biri alınacaktır.', ['Hem pasta hem çiçek alınacaktır.', 'Yalnızca pasta alınacaktır.', 'Ne pasta ne de çiçek alınmayacaktır.'], 'Gelecek kişi Ali ise pasta, Banu ise çiçek alınır; ikisi de gelirse ikisi de alınır. Her durumda en az biri alınmış olur.'),
  ('Bir okulun yönetmeliğinde “Bir öğrenci ancak devamsızlığı 10 günü aşarsa sınıfta kalır.” yazmaktadır. Mert bu yıl sınıfta kalmıştır. Buna göre hangisi kesinlikle doğrudur?', 'Mert\'in devamsızlığı 10 günü aşmıştır.', ['Mert\'in notları yetersiz kalmıştır.', 'Mert hiç devamsızlık yapmamıştır.', 'Devamsızlığı 10 günü aşan herkes sınıfta kalır.'], '“Ancak … -sa” yapısı gerekli koşul bildirir: sınıfta kalan herkesin devamsızlığı 10 günü aşmıştır. Aşan herkesin kaldığı ise söylenmemiştir.'),
  ('Bir yarışmada öğrenci ya notu 90\'ın üstündeyse ya da projesi seçilirse ödül kazanır; koşullardan biri yeterlidir. Defne ödül kazanamamıştır. Buna göre hangisi kesinlikle doğrudur?', 'Defne\'nin notu 90\'ın üstünde değildir ve projesi seçilmemiştir.', ['Defne\'nin notu 90\'ın üstündedir ama projesi seçilmemiştir.', 'Defne\'nin projesi seçilmiş ama notu yetersiz kalmıştır.', 'Defne yarışmaya bir proje göndermemiştir.'], 'Koşullardan herhangi biri sağlansaydı ödül kazanılırdı. Ödül olmadığına göre iki koşul da sağlanmamıştır.'),
  ('Arda yalnızca hava güneşli olduğunda bisiklete biner. Bugün hava güneşlidir. Buna göre Arda için ne söylenebilir?', 'Bisiklete binip binmeyeceği kesin değildir.', ['Arda bugün kesinlikle bisiklete binecektir.', 'Arda bugün kesinlikle bisiklete binmeyecektir.', 'Arda güneşli her gün bisiklete biner.'], '“Yalnızca güneşliyken biner” ifadesi güneşi gerekli koşul yapar, yeterli değil. Güneşli bir günde binmeyebilir de.'),
  ('Bir şifrede sözcüğün önce tek sıradaki harfleri, ardından çift sıradaki harfleri yazılıyor; örneğin ARABA sözcüğü AAARB oluyor. Bu kurala göre KİTAP nasıl yazılır?', 'KTPİA', ['KİTPA', 'KPTİA', 'TKPAİ'], 'Tek sıradakiler K (1.), T (3.), P (5.); çift sıradakiler İ (2.) ve A (4.) harfleridir. Sırayla yazılınca KTPİA olur.'),
  ('İngiliz alfabesinin kullanıldığı bir şifrede her harf, sözcüğün harf sayısı kadar ileri kaydırılıyor; örneğin iki harfli AT sözcüğü CV oluyor. Bu kurala göre BIR nasıl yazılır?', 'ELU', ['CJS', 'DKT', 'FMV'], 'BIR üç harflidir; her harf üç ileri kayar: B→E, I→L, R→U.'),
  ('İngiliz alfabesiyle çalışan bir şifrede sözcük önce tersten yazılıyor, sonra her harf bir ileri kaydırılıyor; örneğin SAL sözcüğü MBT oluyor. Bu kurala göre KUM nasıl yazılır?', 'NVL', ['LVN', 'JTL', 'NUK'], 'KUM tersten MUK olur. Her harf bir ileri kayınca M→N, U→V, K→L ve sonuç NVL\'dir.'),
  ('İngiliz alfabesinden oluşturulan A, B, D, G, K, … dizisinde bir sonraki harf hangisidir?', 'P', ['O', 'Q', 'N'], 'Harfler arasındaki uzaklık her adımda bir artar: +1, +2, +3, +4. Sıradaki adım +5\'tir; K\'den beş harf sonra P gelir.'),
  ('2, A, 4, C, 8, E, 16, G, … dizisinde bir sonraki terim hangisidir?', '32', ['18', 'H', 'I'], 'Dizi iki iç içe diziden oluşur: sayılar her adımda iki katına çıkar, harfler birer atlayarak ilerler. Sıra sayı dizisindedir: 16\'nın iki katı 32.'),
  ('KALEMKALEMKALEM… biçiminde KALEM sözcüğünün art arda yazılmasıyla oluşan harf dizisinde 53. harf hangisidir?', 'L', ['K', 'E', 'M'], 'Desen beş harflik tekrardan oluşur. 53\'ün 5\'e bölümünden kalan 3 olduğundan 53. harf desenin üçüncü harfi olan L\'dir.'),
  ('“Okul servisini kullanan öğrenci sayısı bu yıl azaldı; demek ki aileler servis ücretini pahalı buluyor.” yargısı hangi varsayıma dayanır?', 'Servisten vazgeçmenin başlıca nedeni ücrettir.', ['Okuldaki toplam öğrenci sayısı son yıllarda sürekli olarak artmıştır.', 'Servis araçlarının tamamı yeni model ve klimalı araçlardan oluşmaktadır.', 'Ailelerin çoğu çocuklarını okula yürüyerek göndermeyi tercih etmez.'], 'Azalmayı ücrete bağlamak için başka nedenlerin (taşınma, okulun yakınlaşması gibi) belirleyici olmadığını kabul etmek gerekir.'),
  ('“Kitap fuarına bu yıl iki kat ziyaretçi geldi; demek ki ülkede kitap okuma oranı arttı.” yargısının örtük varsayımı hangisidir?', 'Fuar ziyaretçi sayısı okuma alışkanlığını yansıtır.', ['Fuarda satılan kitapların fiyatları geçen yıla göre düşmüştür.', 'Fuar bu yıl öncekinden daha büyük bir alanda düzenlenmiştir.', 'Ziyaretçilerin önemli bir kısmı başka kentlerden gelmiştir.'], 'Ziyaretçi artışından okuma oranına geçmek için fuara gelenlerin artışının okuyanların artışı anlamına geldiği kabul edilmelidir.'),
  ('Bir belediye, sokak lambalarını LED lambalarla değiştirdikten sonra elektrik faturasının düştüğünü ve bunun LED\'lerden kaynaklandığını açıklıyor. Hangisi bu açıklamayı en çok güçlendirir?', 'Lambaların sayısı ve yanma süreleri değişmeden kalmıştır.', ['LED lambaların ilk satın alma maliyeti eski lambalardan daha yüksektir.', 'Bazı vatandaşlar yeni lambaların ışığını daha soğuk bulmaktadır.', 'Belediye aynı yıl park ve bahçelere yeni bankları da yerleştirmiştir.'], 'Faturayı etkileyebilecek diğer etkenlerin (lamba sayısı, yanma süresi) sabit kaldığının bilinmesi, düşüşün LED\'den kaynaklandığını destekler.'),
  ('Bir dizinin reklam araları kısaltıldıktan sonra izlenme oranı artmış, yapımcı bu artışı reklam süresine bağlamıştır. Hangisi yapımcının açıklamasını en çok zayıflatır?', 'Aynı hafta dizinin en sevilen oyuncusu kadroya geri dönmüştür.', ['Dizinin yayın saati yıllardır hiç değişmeden aynı kalmaktadır.', 'Reklam verenlerin bir kısmı yeni düzenlemeden memnun kalmamıştır.', 'Dizinin önceki sezonları da yüksek izlenme oranlarına ulaşmıştı.'], 'İzlenmeyi artırabilecek başka bir olayın aynı anda gerçekleşmesi, artışın reklam süresinden kaynaklandığı iddiasını zayıflatır.'),
  ('Bir araştırmacı, gürültülü ortamda çalışmanın dikkati dağıttığını ileri sürüyor. Aşağıdakilerden hangisi bu iddiayı en çok destekler?', 'Gürültü arttıkça katılımcıların hata sayısı da düzenli olarak artmıştır.', ['Katılımcıların çoğu sessiz ortamda çalışmayı tercih ettiğini söylemiştir.', 'Gürültülü ortamda çalışan bazı kişiler kulaklık takmayı denemiştir.', 'Deney, şehrin en kalabalık semtindeki bir binada gerçekleştirilmiştir.'], 'Gürültü düzeyi ile hata sayısının birlikte artması, ölçülebilir ve kademeli bir etki olduğunu gösterir; tercihler ise dikkat dağınıklığını kanıtlamaz.'),
  ('“İnsan vücudu bir makineye benzer; makineler bozuk parçası değiştirilerek onarılır; öyleyse her hastalık organ nakliyle tedavi edilmelidir.” akıl yürütmesindeki temel hata nedir?', 'Önemli yönleri farklı iki şey arasında benzetme kurulmuştur.', ['Kanıt olarak yalnızca çoğunluğun görüşü gösterilmiştir.', 'Karşı görüşü savunan kişinin kişiliği hedef alınmıştır.', 'Sonuç, öncüllerden birinin başka sözcüklerle tekrarıdır.'], 'Vücut ile makine arasındaki benzerlik, “her hastalık parça değişimiyle çözülür” sonucunu taşıyacak kadar güçlü değildir; bu, yanlış (zayıf) analojidir.'),
  ('Bir firma web sitesinde ürününü öven beş yorumu yayımlıyor, aynı ürün hakkındaki iki yüz olumsuz yorumu ise göstermiyor. Firma hangi akıl yürütme hatasını yapmaktadır?', 'İşine gelen kanıtları seçip gerisini yok saymak', ['Karşı tarafın görüşünü çarpıtarak çürütmeye çalışmak', 'Bir uzmanın sözünü kanıt yerine kullanmak', 'Seçenekleri yapay biçimde ikiye indirmek'], 'Bütün kanıtlar yerine yalnızca iddiayı destekleyenlerin sunulmasına seçici kanıt (kiraz toplama) hatası denir.'),
  ('Bir tartışmada biri karşısındakine “Kopya çekmeyi ne zaman bıraktın?” diye soruyor. Bu sorudaki sorun nedir?', 'Kanıtlanmamış bir suçlamayı soruya gizlemiştir.', ['Soruda iki farklı kavram aynı sözcükle anlatılmıştır.', 'Soru, karşı tarafın görüşünü abartarak özetlemektedir.', 'Soru, çoğunluğun düşüncesini kanıt olarak sunmaktadır.'], 'Soru hangi biçimde yanıtlanırsa yanıtlansın, kişinin daha önce kopya çektiği kabul edilmiş olur. Buna karmaşık (yüklü) soru denir.'),
  ('Bir ilaç denemesinde ne hastalar ne de onları değerlendiren doktorlar kimin gerçek ilacı kimin etkisiz hapı aldığını bilmektedir. Bu düzenlemenin amacı nedir?', 'Beklentilerin sonuçları etkilemesini önlemek', ['Denemeye katılan hasta sayısını artırabilmek', 'İlacın üretim maliyetini olabildiğince düşürmek', 'Deneme süresini mümkün olduğunca kısaltmak'], 'Hasta ya da doktor gruplamayı bilseydi, umut ya da önyargı değerlendirmeyi etkileyebilirdi. Buna çift kör deney denir.'),
  ('Bir kuyrukta Ayla, Burcu\'dan üç kişi öndedir. Burcu da Cansu\'dan iki kişi arkadadır. Ayla ile Cansu\'nun yerleri için hangisi doğrudur?', 'Ayla, Cansu\'nun hemen önündedir.', ['Cansu, Ayla\'nın hemen önündedir.', 'Ayla ile Cansu arasında iki kişi vardır.', 'Cansu, Ayla\'dan beş kişi öndedir.'], 'Burcu\'nun yeri b ise Ayla b − 3, Cansu b − 2 konumundadır. Ayla, Cansu\'dan bir sıra öndedir.'),
  ('Bir duvar saati her saatte 2 dakika geri kalmaktadır. Pazartesi saat 12.00\'de doğru saate ayarlanmıştır. Salı günü gerçek saat 12.00 olduğunda bu saat neyi gösterir?', '11.12', ['11.48', '11.36', '12.48'], 'Aradan 24 saat geçmiştir; saat 24 × 2 = 48 dakika geri kalmıştır. 12.00\'den 48 dakika eksik 11.12\'dir.'),
  ('2024 yılı artık yıl olduğu için 366 gün çekmiştir ve 1 Ocak 2024 pazartesiye denk gelmiştir. Buna göre 1 Ocak 2025 haftanın hangi günüdür?', 'Çarşamba', ['Salı', 'Perşembe', 'Pazartesi'], '366 gün, 52 hafta artı 2 gündür. Pazartesiden iki gün sonrası çarşambadır.'),
  ('Dünden önceki günden üç gün sonra cumartesi olacaktır. Bugün haftanın hangi günüdür?', 'Cuma', ['Perşembe', 'Pazar', 'Çarşamba'], 'Dünden önceki gün bugünden 2 gün öncedir; ondan 3 gün sonrası bugünden 1 gün sonradır. Yarın cumartesi ise bugün cumadır.'),
  ('Bir kavşaktaki yön tabelası fırtınada saat yönünde 90° dönmüştür; tabelada “Kuzey” yazan kol artık gerçekte doğuyu göstermektedir. Tabelada “Batı” yazan kol şimdi gerçekte hangi yönü gösterir?', 'Kuzeyi', ['Güneyi', 'Doğuyu', 'Batıyı'], 'Her kol saat yönünde 90° kaymıştır: kuzey doğuya, doğu güneye, güney batıya, batı da kuzeye döner.'),
  ('Bir mağazadaki her ürünün ya indirimi ya da hediyesi vardır; ikisi birden olmaz. Hediyeli ürünlerin hepsi kırmızı etiketlidir ve etiketler yalnızca kırmızı ya da mavidir. Mavi etiketli bir ürün alan müşteri için hangisi kesindir?', 'Aldığı ürün indirimlidir.', ['Aldığı ürünün yanında bir hediye vardır.', 'Aldığı ürün hem indirimli hem hediyelidir.', 'Aldığı ürün ne indirimli ne de hediyelidir.'], 'Mavi etiketli ürün hediyeli olamaz, çünkü hediyeliler kırmızı etiketlidir. Her ürünün iki özellikten biri olduğuna göre ürün indirimlidir.'),
  ('Bir kutuda kırmızı, mavi ve yeşil renkte onar kalem vardır. Gözü kapalı biri en az kaç kalem alırsa elinde en az iki farklı renkte kalem bulunacağı kesinleşir?', '11', ['2', '4', '21'], 'En kötü durumda ilk 10 kalemin hepsi aynı renkte olabilir. 11. kalem mutlaka başka bir renktendir.'),
  ('Bir satranç turnuvasında her oyuncu diğer her oyuncuyla tam bir kez oynamış ve toplam 10 oyun oynanmıştır. Turnuvaya kaç oyuncu katılmıştır?', '5', ['4', '6', '10'], 'n oyuncu arasında n·(n − 1)/2 oyun oynanır. 5 oyuncuda 5·4/2 = 10 oyun olur.'),
  ('Bir kargo şirketi şu kuralı uygular: Kırılacak eşya uzak bir kente gidiyorsa ekspres ve korumalı paketlenir; kırılacak eşya yakın bir kente gidiyorsa standart korumalı paketlenir; kırılmayan her eşya standart paketlenir. Uzak bir kente gönderilen kitap paketi nasıl hazırlanır?', 'Korumasız, standart bir pakette gönderilir.', ['Ekspres ve korumalı paketlenerek gönderilir.', 'Standart ama korumalı biçimde paketlenir.', 'Korumasız, yalnızca ekspres gönderilir.'], 'Kitap kırılacak eşya değildir; bu yüzden gideceği kentin uzaklığına bakılmaz ve standart paketlenir.'),
  ('Bir adada yaşayanlar ya hep doğru ya da hep yalan söyler. Ahmet “İkimiz de doğrucuyuz.” derken Berna “İkimizden en az biri yalancıdır.” diyor. Bu iki kişinin türleri nedir?', 'Ahmet yalancı, Berna doğrucu', ['İkisinin de doğrucu olduğu anlaşılır', 'Ahmet doğrucu, Berna yalancıdır', 'İkisinin de yalancı olduğu anlaşılır'], 'İki söz birbirinin tam tersidir; biri doğru, biri yanlıştır. Ahmet\'in sözü doğru olsaydı Berna da doğrucu olurdu ve Berna\'nın sözü yanlış çıkardı. Doğru söyleyen Berna\'dır.'),
  ('Bir sitede yalnızca site üyeleri yüzme havuzunu kullanabilmektedir ve bu kurala uyulmaktadır. Bazı üniversite öğrencilerinin bu havuzu kullandığı görülmüştür. Buna göre hangisi kesinlikle doğrudur?', 'Bazı üniversite öğrencileri site üyesidir.', ['Bütün site üyeleri üniversite öğrencisidir.', 'Her üniversite öğrencisi siteye üyedir.', 'Havuzu kullanan herkes üniversite öğrencisidir.'], 'Havuzu kullanan herkes üyedir. Havuzu kullanan öğrenciler de bu yüzden üyedir; dolayısıyla en az bazı öğrenciler üyedir.'),
  ('Uydurma sözcüklerle verilen “Hiçbir lorp mavi değildir.” ve “Bütün zinkler mavidir.” öncüllerinden hangi sonuç kesinlikle çıkar?', 'Hiçbir zink lorp değildir.', ['Bazı zinkler lorptur.', 'Bütün lorplar zinktir.', 'Mavi olan her şey zinktir.'], 'Zinklerin hepsi mavi, lorpların hiçbiri mavi olduğundan iki kümenin ortak öğesi olamaz.'),
  ('Bir köyde her insan ya hep doğru ya hep yalan konuşur. Kenan, Lale için “O bir yalancı.” derken Lale de “Kenan\'la benim türlerimiz birbirinden farklı.” karşılığını veriyor. Buna göre hangisi doğrudur?', 'Kenan yalancı, Lale doğrucudur.', ['Kenan doğrucu, Lale ise yalancıdır.', 'İkisi de aynı türden, doğrucudur.', 'İkisi de aynı türden, yalancıdır.'], 'Kenan doğrucu olsaydı Lale yalancı olurdu; ama o zaman Lale\'nin “farklıyız” sözü doğru çıkardı. Kenan yalancıdır, Lale doğrucudur ve gerçekten farklıdırlar.'),
  ('Bir adada yaşayanlar ya doğrucudur (her zaman doğruyu söyler) ya da yalancıdır (her zaman yalan söyler). Karşılaştığınız birinin doğrucu mu yalancı mı olduğunu tek bir soruyla anlamak istiyorsunuz. Aşağıdaki sorulardan hangisi bu amaca uygundur?', '“İki artı iki dört eder mi?”', ['“Sen bir doğrucu musun?”', '“Sen bir yalancı mısın?”', '“Bu adada mı yaşıyorsun?”'], 'Yanıtı herkesçe bilinen bir soruda doğrucu “evet”, yalancı “hayır” der. Kişinin kendi türünü sormak işe yaramaz, çünkü iki tür de aynı yanıtı verir.'),
  ('Bir öğretmen A, B, C ve D sınıflarına art arda birer saat ders verecektir. A ile B sınıflarının dersleri arka arkaya gelmeyecektir. Öğretmen derslerin sırasını kaç farklı biçimde belirleyebilir?', '12', ['18', '6', '24'], 'Dört sınıf 24 farklı sırada dizilebilir. A ile B\'nin yan yana olduğu dizilişler 2 × 3! = 12 tanedir. Geriye 24 − 12 = 12 diziliş kalır.'),
  ('Bir projede dört iş vardır: A işi 3 gün, B işi 2 gün, C işi 4 gün, D işi 1 gün sürer. B, A bittikten sonra; D ise hem B hem C bittikten sonra başlayabilir. İki ekip aynı anda farklı işlerde çalışabiliyorsa proje en erken kaç günde biter?', '6 günde', ['10 günde', '5 günde', '7 günde'], 'Bir ekip A ve B\'yi 5 günde bitirirken öteki ekip C\'yi 4 günde bitirir. D, 5. günün sonunda başlar ve 6. gün biter.'),
  ('Bir sinemada 12 yaşından küçük çocuklar salona ancak bir yetişkinle girebilir; 7 yaşından küçük çocuklar ise akşam seansına hiçbir şekilde alınmaz. 6 yaşındaki Efe, annesiyle birlikte akşam seansına gelmiştir. Efe için hangisi doğrudur?', 'Efe akşam seansına giremez.', ['Annesi yanında olduğu için Efe salona girebilir.', 'Efe yalnız gelseydi akşam seansına girebilirdi.', 'Efe\'nin girebilmesi için iki yetişkin gerekir.'], 'Efe 7 yaşından küçük olduğu için akşam seansı yasağı geçerlidir; yetişkinle gelmesi bu yasağı kaldırmaz.'),
  ('Bir acil serviste hastalar şu öncelikle muayene edilir: önce hayati tehlikesi olanlar, sonra 65 yaş üstündekiler, en son da geliş sırasına göre diğerleri. Ayşe (30 yaşında, hayati tehlikesi yok) ilk, Bekir (70 yaşında, hayati tehlikesi yok) ikinci, Cemal (40 yaşında, hayati tehlikesi var) üçüncü gelmiştir. Muayene sırası nasıl olur?', 'Cemal, Bekir, Ayşe', ['Ayşe, Bekir, Cemal', 'Bekir, Cemal, Ayşe', 'Cemal, Ayşe, Bekir'], 'Hayati tehlikesi olan Cemal önce, 65 yaş üstündeki Bekir ikinci sırada muayene edilir. Geliş sırası yalnızca Ayşe için belirleyicidir.'),
  ('Bir kafedeki her müşteri ya çay ya da kahve içmektedir. Çay içenlerin hepsi çayını şekerli içer. Bugün kafede içeceğini şekersiz içen bir müşteri görülmüştür. Buna göre hangisi kesinlikle doğrudur?', 'Kafede kahve içen en az bir müşteri vardır.', ['Kafedeki her müşteri kahve içmektedir.', 'Kahve içen hiçbir müşteri şeker kullanmamaktadır.', 'Kafede çay içen hiç kimse bulunmamaktadır.'], 'Şekersiz içen müşteri çay içiyor olamaz; öyleyse kahve içmektedir. Diğer müşteriler hakkında bir şey söylenemez.'),
  ('“Ateş : duman” ilişkisine en çok benzeyen ikili hangisidir?', 'Sürtünme : ısı', ['Duman : baca', 'Ağaç : yaprak', 'Kalem : kâğıt'], 'Ateş dumanı ortaya çıkarır; sürtünme de ısı oluşturur. İki ikilide de neden-sonuç ilişkisi vardır.'),
  ('Bir şehir merkezine araç girişi plakaya göre düzenlenmiştir: Son rakamı tek olan araçlar haftanın ilk, üçüncü ve beşinci günleri; son rakamı çift olan araçlar salı, perşembe ve cumartesi girebilir; pazar günü bütün araçlar girebilir. Plakası 128 ile biten bir araç aşağıdaki günlerden hangisinde merkeze giremez?', 'Çarşamba', ['Salı', 'Pazar', 'Cumartesi'], 'Plakanın son rakamı 8, yani çifttir. Çift plakalar salı, perşembe, cumartesi ve pazar girebilir; çarşamba giremez.'),
  ('Bir torbada toplam 5 bilye vardır ve bilyeler yalnızca kırmızı ya da mavidir. Torbada en az bir kırmızı bilye bulunur ve kırmızıların sayısı mavilerden azdır. Buna göre hangisi kesinlikle doğrudur?', 'Torbada en az üç mavi bilye vardır.', ['Torbada tam olarak iki kırmızı bilye vardır.', 'Mavi bilyelerin sayısı dörde eşittir.', 'Kırmızı ve mavi bilyelerin sayısı eşittir.'], 'Kırmızı 1 ise mavi 4, kırmızı 2 ise mavi 3\'tür; kırmızı 3 olursa maviden fazla olur. İki durumda da mavi en az üçtür.'),
  ('Bir sırada baştan sona Ali, Banu, Cem ve Deniz bulunmaktadır. Bir işlemde önce baştaki kişi en sona geçer, ardından ikinci ve üçüncü sıradaki kişiler yer değiştirir. Bu işlem art arda iki kez uygulanırsa en sonda kim bulunur?', 'Banu', ['Ali', 'Cem', 'Deniz'], 'İlk işlemden sonra sıra Banu, Deniz, Cem, Ali olur. İkinci işlemde Banu sona geçer ve Deniz, Ali, Cem, Banu elde edilir.'),
  ('Bay geçme olmayan, tek maçlık eleme usulü bir tenis turnuvasında şampiyon toplam 4 maç oynamış ve hepsini kazanmıştır. Turnuvaya kaç oyuncu katılmıştır?', '16', ['8', '4', '32'], 'Her turda oyuncu sayısı yarıya iner ve şampiyon her turda bir maç oynar. Dört tur, 16 → 8 → 4 → 2 → 1 düzenine karşılık gelir.'),
  ('Üç takımlı bir turnuvada A, B\'yi; B, C\'yi; C de A\'yı yenmiştir ve başka maç oynanmamıştır. Bu sonuçlarla ilgili hangisi doğrudur?', 'Hangi takımın en güçlü olduğu bu sonuçlardan çıkarılamaz.', ['A takımı, C takımından kesinlikle daha güçlü bir takımdır.', 'B takımı turnuvanın en güçlü takımıdır.', 'C takımı, B\'ye kesinlikle yenilirdi.'], 'Sonuçlar bir döngü oluşturur; “yendi” ilişkisi burada geçişli değildir. Her takım bir kez kazanıp bir kez kaybettiği için kesin bir sıralama yapılamaz.'),
  ('Oya, Pars ve Rüya\'nın meslekleri ressam, şef ve avukattır; İzmir, Muğla ve Rize\'de yaşarlar (her biri farklı). Oya Rize\'de yaşamaz. Şef Muğla\'da yaşar. Pars şef değildir ve İzmir\'de yaşamaz. Rüya avukattır. Oya hangi kentte yaşar?', 'Muğla', ['İzmir', 'Rize', 'Belirlenemez'], 'Rüya avukat, Pars şef olmadığına göre şef Oya\'dır ve Muğla\'da yaşar. Pars İzmir\'de yaşamadığı için Rize\'dedir, Rüya da İzmir\'dedir.'),
  ('Bir derste şu kural geçerlidir: “Ödevini teslim eden ve sınava giren her öğrenci dersi geçer.” Ayla bu dersi geçememiştir. Buna göre hangisi kesinlikle doğrudur?', 'Ayla ya ödevini teslim etmemiş ya da sınava girmemiştir.', ['Ayla ödevini teslim etmiş ama sınava girmemiştir.', 'Ayla sınava girmiş ama ödevini teslim etmemiştir.', 'Ayla hem ödevini vermiş hem de sınava girmiş, yine de geçememiştir.'], 'İki koşul birlikte sağlansaydı Ayla dersi geçerdi. Geçemediğine göre en az biri eksiktir; hangisinin eksik olduğu bilinemez.'),
  ('“Sınavı kazanmak için çok çalışmak gereklidir ama yeterli değildir.” cümlesiyle uyumlu olan durum hangisidir?', 'Çok çalışıp sınavı kazanamayan biri vardır.', ['Hiç çalışmadan sınavı kazanan biri vardır.', 'Çok çalışan herkes sınavı kesinlikle kazanır.', 'Sınavı kazanan herkes az çalışmıştır.'], 'Gereklilik, kazanan herkesin çok çalıştığını; yetersizlik ise çok çalışan bazı kişilerin kazanamayabileceğini anlatır.'),
  ('Bir istasyonda “Ancak bilet alanlar trene binebilir.” kuralı uygulanmaktadır. Aşağıdaki durumlardan hangisi bu kurala aykırı değildir?', 'Bilet alıp trene binmeyen bir yolcu', ['Bilet almadan trene binen bir yolcu', 'Biletsiz olarak vagona geçen bir çocuk', 'Bilet almadan son vagona atlayan biri'], 'Kural yalnızca biletsiz binmeyi yasaklar. Bilet alıp vazgeçmek kurala aykırı değildir; bilet gerekli koşuldur, binmeyi zorunlu kılmaz.'),
  ('Bir yarışmanın kuralına göre hiçbir öğretmen yarışmaya katılamaz. Bazı ressamlar aynı zamanda öğretmendir. Buna göre hangisi kesinlikle doğrudur?', 'Bazı ressamlar yarışmaya katılamaz.', ['Hiçbir ressam yarışmaya katılamaz.', 'Bütün ressamlar yarışmaya katılır.', 'Yarışmaya yalnızca ressamlar katılır.'], 'Öğretmen olan ressamlar yarışmaya katılamaz; öğretmen olmayan ressamlar hakkında ise bilgi yoktur.'),
  ('“Bütün başarılı öğrenciler düzenli uyur.” önermesi doğru kabul edilirse aşağıdakilerden hangisi bu önermeden çıkarılamaz?', 'Düzenli uyuyan her öğrenci başarılıdır.', ['Düzenli uyumayan bir öğrencinin başarılı olmadığı söylenebilir.', 'Başarılı olup düzenli uyumayan bir öğrenci bulunmaz.', 'Bir öğrenci başarılıysa düzenli uyuyor demektir.'], 'Önermenin tersi (“düzenli uyuyan başarılıdır”) önermeden çıkmaz. Diğerleri önermenin kendisi ya da karşıt tersidir.'),
  ('“Her parlayan şey altın değildir.” atasözünde anlatılmak istenen mantıksal yargı hangisidir?', 'Parlayan şeylerin bazıları altın değildir.', ['Parlayan hiçbir şey altından yapılmamıştır.', 'Altından yapılmış her şey parlak görünür.', 'Parlamayan her şey altındır.'], '“Her … değildir” yapısı burada “hepsi değil, bazıları değil” anlamındadır; parlayan şeylerin tümünün altın olmadığı söylenir.'),
  ('Dört arkadaş için şunlar bilinmektedir: Ali pikniğe giderse Burak da gider. Cem gitmezse Deniz gider. Burak ile Deniz birlikte gitmez. Ali pikniğe gitmiştir. Kimlerin gittiği kesindir?', 'Ali, Burak ve Cem', ['Ali ile Deniz', 'Ali, Burak ve Deniz', 'Yalnızca Ali ile Burak'], 'Ali gittiği için Burak gider; Burak gittiği için Deniz gitmez; Deniz gitmediğine göre Cem gitmiştir (aksi hâlde Deniz giderdi).'),
  ('Ahmet Bey\'in torununun torunu, Ahmet Bey\'den kaç kuşak sonra gelir?', '4', ['2', '3', '5'], 'Çocuk 1, torun 2, torunun çocuğu 3, torunun torunu 4 kuşak sonradır.'),
  ('Bir duvar saati, 12 rakamı kuzeyi gösterecek biçimde yere yatırılmıştır. Saat 7.30\'u gösterdiğinde yelkovanın ucu hangi yönü gösterir?', 'Güneyi', ['Kuzeyi', 'Doğuyu', 'Batıyı'], 'Saat başı ile buçuk arasında yelkovan 6\'ya gelir. 12 kuzeyi gösterdiğine göre 6 rakamı güneydedir.'),
  ('Bir ayın 5. günü salıya denk gelmiştir. Aynı ayın üçüncü cuması ayın kaçıncı günüdür?', '15', ['13', '19', '22'], '5 salı ise 1 cuma olur. Cumalar 1, 8 ve 15\'tir; üçüncü cuma 15\'idir.'),
  ('30 gün çeken bir ayın ilk günü pazartesidir. Bu ayda toplam kaç tane cumartesi ve pazar günü vardır?', '8', ['9', '10', '7'], 'Cumartesiler 6, 13, 20, 27; pazarlar 7, 14, 21, 28\'dir. 29 salı, 30 çarşambadır; toplam sekiz gün eder.'),
  ('Bir evde saat 22.00\'de ışığın yandığı, 23.00\'te sönük olduğu görülmüştür. Komşu 22.30\'da bir çığlık duymuştur ve ışığın çığlıktan önce söndüğü kesin olarak bilinmektedir. Işık hangi zaman aralığında sönmüştür?', '22.00 ile 22.30 arasında', ['22.30 ile 23.00 arasında', 'Saat 23.00\'ten sonraki bir anda', '22.00\'den önce'], 'Işık 22.00\'de yanıyordu ve 22.30\'daki çığlıktan önce söndü. Bu iki bilgi aralığı 22.00 ile 22.30 arasına daraltır.'),
  ('Bir tartışmada biri bir sorunun yanıtına 4, öteki 6 diyor. Dinleyen biri “Doğrusu ikisinin ortası olan 5\'tir.” diyor. Bu yaklaşımdaki hata nedir?', 'İki uç arasındaki orta noktanın doğru olduğunu varsaymak', ['Bir uzmanın görüşüne kanıt yerine başvurarak sonuca varmak', 'Az sayıda örnekten genelleme yapmak', 'Karşı tarafın kişiliğini eleştirmek'], 'Doğru yanıt uçlardan biri ya da bambaşka bir değer olabilir. İki görüşün ortasını kendiliğinden doğru saymak orta yol yanılgısıdır.'),
  ('“Bitkiler büyüyebilmek için toprağa ihtiyaç duyar.” hipotezini aşağıdaki gözlemlerden hangisi çürütür?', 'Topraksız, yalnızca besinli suda yetiştirilen bir bitkinin büyümesi', ['Toprağa ekilen bir bitkinin birkaç hafta içinde hızla büyüyüp çiçek açması', 'Kuru toprakta bir bitkinin solup kuruması', 'Gölgede kalan bir bitkinin yavaş büyümesi'], 'Hipotez toprağı zorunlu sayar. Toprak olmadan büyüyen tek bir bitki bu zorunluluğu çürütür.'),
  ('Beş katlı bir binada Ece, Fırat, Gizem, Hande ve İlker farklı katlarda oturur. Ece, Fırat\'tan iki kat yukarıdadır. Hande, Ece\'nin hemen altındaki katta oturur. Gizem en üst katta, Fırat da 1. katta oturmaz. Buna göre hangisi kesinlikle yanlıştır?', 'İlker 3. katta oturur.', ['Gizem 2. katta oturur.', 'Ece en üst katta oturur.', 'Fırat 3. katta oturur.'], 'Fırat-Hande-Ece art arda üç kat kaplar ve Fırat 1. katta değildir; üçlü 2-3-4 ya da 3-4-5. katlara yerleşir. Her iki durumda da 3. kat bu üçlüden birine ait olduğundan İlker 3. katta olamaz.'),
  ('Bir okulda şu kurallar geçerlidir: Kopya çeken öğrenci sınavdan çıkarılır. Sınavdan çıkarılan öğrenci o sınavdan sıfır alır. Sıfır alan öğrenci bütünleme sınavına giremez. Selin bir sınavda kopya çekerken yakalanmıştır. Buna göre hangisi kesinlikle doğrudur?', 'Selin bütünleme sınavına giremez.', ['Selin sınavı yeniden yapılacak bir oturumda tamamlar.', 'Selin yalnızca bütünleme sınavına girebilir.', 'Selin\'in notu, sınavın yarısına göre hesaplanır.'], 'Kurallar zincir oluşturur: kopya → sınavdan çıkarılma → sıfır → bütünlemeye girememe.'),
  ('Bir torbada 3 kırmızı ve 2 mavi top vardır. Torbadan bakmadan 3 top çekilmiştir. Çekilen toplar için hangisi kesinlikle doğrudur?', 'En az biri kırmızıdır.', ['En az biri mavidir.', 'Tam olarak ikisi kırmızıdır.', 'Üçü de farklı renktedir.'], 'Torbada yalnızca 2 mavi top olduğundan 3 topun hepsi mavi olamaz; en az biri kırmızıdır. Üçü de kırmızı olabileceği için mavi çıkması kesin değildir.'),
  ('Ali\'nin cebinde toplam değeri 6 lira olan üç madeni para vardır. Paralar yalnızca 1, 2 ya da 5 liralık olabilir. Buna göre hangisi kesinlikle doğrudur?', 'Paraların üçü de 2 liralıktır.', ['Paralardan biri 5 liralıktır.', 'Paralardan ikisi 1 liralıktır.', 'Paralardan biri 1, biri de 5 liralıktır.'], '5 liralık bir para olursa kalan iki paranın toplamı 1 lira olmalıdır; bu mümkün değildir. 1 ve 2 liralıklarla üç parada 6 lirayı yalnızca 2 + 2 + 2 verir.'),
  ('Aynı deney iki kez yapılmış ve iki farklı sonuç elde edilmiştir. Araştırmacının ilk olarak neyi incelemesi en uygun olur?', 'İki deneyin koşullarının gerçekten aynı olup olmadığını', ['Hangi sonucun kendi beklentisine daha uygun olduğunu', 'Deneyi yapan kişilerin kaç yıllık deneyimi olduğunu', 'Sonuçlardan hangisinin daha ilginç göründüğünü'], 'Farklı sonuçlar çoğu zaman fark edilmemiş bir koşul değişikliğinden kaynaklanır. Önce koşulların eşitliği denetlenir.'),
  ('“Kemal her sabah yarım saat koşuyor; bu yüzden maratonu rahatlıkla bitirebilir.” akıl yürütmesindeki örtük varsayım hangisidir?', 'Sabah koşuları maraton için yeterli dayanıklılık kazandırır.', ['Kemal maratonu daha önce de en az bir kez bitirmiştir.', 'Maraton parkuru Kemal\'in evine çok yakın bir yerdedir.', 'Kemal koşmaya birkaç yıl önce başlamıştır.'], 'Yarım saatlik koşulardan maraton başarısına geçmek için bu antrenmanın yeterli olduğunu kabul etmek gerekir.'),
  ('Bir belediye, yeni kavşak düzenlemesinden sonra o yoldaki kazaların azaldığını ve bunu kavşağın sağladığını açıklıyor. Hangisi bu açıklamayı en çok zayıflatır?', 'Aynı dönemde o yoldan geçen araç sayısı yarıya inmiştir.', ['Kavşak düzenlemesi planlanandan iki ay geç bitirilmiştir.', 'Kavşakta kullanılan trafik ışıkları yerli üretimdir.', 'Kavşağın çevresine yeni ağaçlar da dikilmiştir.'], 'Trafik yarıya indiyse kazaların azalması bu nedenle de açıklanabilir; azalmanın kavşaktan kaynaklandığı kesinleşmez.'),
  ('Bir okul, teneffüslerde telefon kullanımını yasakladıktan sonra öğrencilerin daha çok kitap okuduğunu ileri sürüyor. Hangisi bu iddiayı en çok güçlendirir?', 'Yasaktan önceye göre kütüphaneden alınan kitap sayısı belirgin biçimde artmıştır.', ['Öğrencilerin çoğu yasağın gereksiz olduğunu düşündüğünü belirtmiştir.', 'Okul kütüphanesi yasaktan bir yıl önce yenilenmiş ve genişletilmiştir.', 'Bazı öğretmenler de teneffüslerde telefon kullanmamaya başlamıştır.'], 'İddia okuma davranışında bir değişim ileri sürdüğü için öncesi ve sonrası karşılaştırılan ölçülebilir bir artış en güçlü destektir.'),
  ('B, E, J ve Q harfleri belli bir kurala göre sıralanmıştır. Kurala uyan beşinci harf hangisidir? (26 harfli İngiliz alfabesi)', 'Z', ['X', 'Y', 'W'], 'Harfler arasındaki atlamalar 3, 5, 7 biçiminde ikişer artmaktadır. Q\'dan sonra 9 harf ileri gidilince Z bulunur.'),
  ('Bir dizide MN, LO ve KP terimleri sırayla yer alıyor. Aynı kural sürdürülürse dördüncü terim ne olmalıdır? (İngiliz alfabesi)', 'JQ', ['JR', 'IQ', 'KQ'], 'Her terimin ilk harfi alfabede birer geri (M, L, K, J), ikinci harfi birer ileri (N, O, P, Q) gider.'),
  ('Bir yetişkin ile iki çocuk küçük bir kayıkla nehrin karşısına geçecektir. Kayık bir seferde ya yalnızca yetişkini ya da en çok iki çocuğu taşıyabilir ve her seferde kayıkta en az bir kişi bulunmalıdır. Üçünün de karşıya geçmesi için en az kaç geçiş gerekir?', '5', ['3', '4', '7'], 'İki çocuk geçer, biri geri döner; yetişkin geçer, karşıdaki çocuk geri döner; son olarak iki çocuk birlikte geçer. Toplam beş geçiş yapılır.'),
  ('Zeynep\'in babasının tek kız kardeşi Nur Hanım\'dır. Nur Hanım\'ın oğlu Ali, Zeynep\'in annesine hangi akrabalık adıyla seslenir?', 'Yenge', ['Teyze', 'Hala', 'Abla'], 'Zeynep\'in babası, Ali\'nin annesinin erkek kardeşi yani Ali\'nin dayısıdır. Dayının eşine yenge denir.'),
  ('Cemil Bey\'in kızının oğlunun babası, Cemil Bey\'in nesidir?', 'Damadı', ['Oğlu', 'Torunu', 'Kardeşi'], 'Kızının oğlunun babası, kızının eşidir. Bir kişinin kızının eşine damat denir.'),
  ('Kuzeydoğuya bakan bir gözcü saat yönünde 135° dönmüştür. Gözcü artık hangi yöne bakmaktadır?', 'Güneye', ['Doğuya', 'Güneybatıya', 'Güneydoğuya'], 'Kuzeydoğu, kuzeyden saat yönünde 45°\'dir. 45° + 135° = 180° olur ve bu güney yönüdür.'),
  ('Kare bir masanın her kenarına bir kişi, yüzü masanın ortasına dönük biçimde oturmuştur. Masanın doğu kenarında oturan kişinin sağ eli hangi yönü gösterir?', 'Kuzeyi', ['Güneyi', 'Doğuyu', 'Batıyı'], 'Doğu kenarındaki kişi masanın ortasına, yani batıya bakar. Batıya bakan birinin sağ tarafı kuzeydir.'),
  ('12 Haziran salı gününe denk gelmiştir. Haziran ayı 30 gün çektiğine göre 12 Temmuz haftanın hangi günüdür?', 'Perşembe', ['Salı', 'Çarşamba', 'Cuma'], '12 Haziran ile 12 Temmuz arasında 30 gün vardır. 30 gün dört hafta artı iki gündür; salıdan iki gün sonra perşembedir.'),
  ('Bir çekmecede yedi farklı renkte çoraplar karışık hâlde durmaktadır; her renkten çok sayıda vardır. Karanlıkta en az kaç tek çorap alınırsa aynı renkten bir çift elde edilmesi garanti olur?', '8', ['7', '2', '14'], 'En kötü durumda ilk yedi çorabın her biri farklı renkte olabilir. Sekizinci çorap bu renklerden biriyle eşleşir.'),
  ('Bir müdür “Notu 50\'nin altında olan öğrenciler ek ödev yapacak.” demiş ve bu kurala eksiksiz uyulmuştur. Ece ek ödev yapmamıştır. Buna göre hangisi kesinlikle doğrudur?', 'Ece\'nin notu 50 ya da daha yüksektir.', ['Ece\'nin notu 50\'nin altındadır.', 'Ece\'nin notu tam olarak 50\'dir.', 'Ece okulun en başarılı öğrencisidir.'], 'Notu 50\'nin altında olan herkes ödev yapmıştır. Ödev yapmayan Ece bu gruba giremez.'),
  ('Uydurma sözcüklerle verilen “Hiçbir glim gece uçmaz.” ve “Bazı tarlar gece uçar.” öncüllerinden hangi sonuç kesinlikle çıkar?', 'Bazı tarlar glim değildir.', ['Hiçbir tar glim değildir.', 'Bazı glimler tardır.', 'Bütün tarlar gece uçar.'], 'Gece uçan tarlar glim olamaz, çünkü glimlerin hiçbiri gece uçmaz. Gece uçmayan tarlar hakkında ise bilgi yoktur.'),
  ('“Bu restoranın aşçısı ünlü bir aşçılık okulundan mezun olmuştur; bu yüzden yemekleri lezzetlidir.” yargısının örtük varsayımı hangisidir?', 'İyi bir okuldan mezun olmak iyi yemek yapmayı sağlar.', ['Restoranın fiyatları bölgedeki ortalamanın oldukça üstündedir.', 'Aşçı mezun olduktan sonra yurt dışında da birkaç yıl çalışmıştır.', 'Restoranın müşterilerinin çoğu aynı semtte oturan kişilerdir.'], 'Mezuniyetten lezzete geçebilmek için okulun iyi yemek yapma becerisi kazandırdığı kabul edilmelidir.'),
  ('“Şehre yeni bir metro hattı yapılırsa hava kirliliği azalır.” öngörüsü hangi varsayıma dayanır?', 'Metroyu kullanacak kişilerin bir kısmı şu an kirletici araçlarla yolculuk etmektedir.', ['Metro hattının yapımı birkaç yıl sürecek ve oldukça pahalı olacaktır.', 'Şehirdeki hava kirliliğinin tek nedeni fabrika bacalarıdır.', 'Metro istasyonları şehrin yalnızca merkezî semtlerinde bulunacaktır.'], 'Kirliliğin azalması için metronun kirletici taşıtların yerini alması gerekir; bu da bazı yolcuların şu an bu taşıtları kullandığını varsayar.'),
  ('Bir öğretmen, sınıftaki oturma düzenini değiştirmenin öğrencilerin derse katılımını artırdığını düşünüyor. Hangisi bu düşünceyi en çok destekler?', 'Oturma düzeninin değişmediği paralel sınıfta katılımda bir değişim görülmemiştir.', ['Öğrencilerin çoğu yeni oturma düzenini daha eğlenceli bulduğunu söylemiştir.', 'Oturma düzeni değiştirilen sınıf okulun en kalabalık sınıfıdır.', 'Öğretmen bu yöntemi başka bir okulda da denemeyi planlamaktadır.'], 'Benzer bir sınıfta değişiklik yapılmadığında katılımın aynı kalması, artışın oturma düzeninden kaynaklandığını destekler.'),
  ('Bir şehirde son beş yılda bisiklet yollarının uzunluğu iki katına çıkmış ve aynı dönemde bisiklet kazaları azalmıştır. Bu bilgilere dayanarak aşağıdaki yargılardan hangisine varılamaz?', 'Bisiklet yolları kazaları kesinlikle azaltmıştır.', ['Son beş yılda bisiklet yolları uzamıştır.', 'Aynı dönemde bisiklet kazalarında bir düşüş olmuştur.', 'Bisiklet yolu uzunluğu ile kazalar aynı dönemde değişmiştir.'], 'İki değişikliğin aynı dönemde olması nedensellik kanıtı değildir; kazalar başka nedenlerle de azalmış olabilir.'),
  ('Aşağıdakilerden hangisi deneyle sınanabilecek bir tahmindir?', 'Bu tohumlar 25 °C\'de bir hafta içinde çimlenecektir.', ['Bu tohumlar bir gün mutlaka başka bir şeye dönüşecektir.', 'Bu tohumlar doğanın vazgeçilmez bir parçasıdır.', 'Bu tohumlardan belki de güzel çiçekler açabilir.'], 'Sınanabilir bir tahmin, ölçülebilir koşul ve süre içerir; yanlışsa deneyle gösterilebilir.'),
  ('Bir öğrenci, kantinde pizza satılan üç günün üçünde de yağmur yağdığını görüp “Pizza günleri yağmur getiriyor.” diyor. Bu çıkarıma yöneltilebilecek en uygun eleştiri hangisidir?', 'Üç gözlem rastlantı olabilir ve aralarında bir neden bağı gösterilmemiştir.', ['Pizza yerine başka bir yemek seçilseydi sonuç kesinlikle değişirdi.', 'Öğrencinin gözlemleri yağmurlu bir mevsimde yapıldığı için sonuç kesindir.', 'Kantindeki pizza satışlarının artması yağmuru açıklamaya yeterlidir.'], 'Çok az sayıda eş zamanlı olay rastlantı sonucu bir araya gelebilir. Nedensellik için mantıklı bir mekanizma ve çok daha fazla veri gerekir.'),
  ('Bir kitap kulübünde o ay en az bir kitap okuyan üyeler kulüp oylamalarına katılabilir. Art arda üç ay hiç kitap okumayan üye kulüpten çıkarılır. Ece son iki aydır hiç kitap okumamıştır. Bu ay için Ece hakkında hangisi doğrudur?', 'Ece oy kullanamaz ama kulüpten de çıkarılmaz.', ['Ece hem oy kullanabilir hem kulüpte kalır.', 'Ece oy kullanabilir ama kulüpten çıkarılır.', 'Ece hem oy hakkını kaybeder hem kulüpten çıkarılır.'], 'Bu ay kitap okumadığı için oy hakkı yoktur. Okumadığı ay sayısı henüz üç olmadığından çıkarılmaz.'),
  ('Bir sepette yalnızca elma ve armut olmak üzere toplam 10 meyve vardır. Elmaların sayısı armutların sayısından fazladır. Buna göre hangisi kesinlikle doğrudur?', 'Sepette en az 6 elma vardır.', ['Sepette tam olarak 6 elma bulunur.', 'Sepette en az 5 tane armut bulunur.', 'Elma ve armutların sayısı birbirine eşittir.'], 'Elmalar 5 olsaydı armutlarla eşit olurdu. Fazla olabilmesi için elmalar en az 6 olmalıdır.'),
  ('Ali, Banu ve Cem\'in boyları birbirinden farklıdır. Ali en uzun, Cem de en kısa değildir. Buna göre hangisi kesinlikle doğrudur?', 'Cem, Ali\'den uzundur.', ['Banu en uzun kişidir.', 'Ali en kısa kişidir.', 'Banu, Cem\'den uzundur.'], 'Olası sıralamalar Banu-Cem-Ali, Cem-Ali-Banu ve Cem-Banu-Ali\'dir. Üçünde de Cem, Ali\'nin önündedir.'),
  ('Elif bir hafta boyunca en az üç gün yüzmüş ve en az üç gün koşmuştur; aynı gün iki sporu birden yapmamıştır. Buna göre hangisi kesinlikle doğrudur?', 'Elif\'in hiç spor yapmadığı en fazla bir gün vardır.', ['Elif haftanın her günü spor yapmıştır.', 'Elif tam olarak üç gün yüzmüştür.', 'Elif\'in hiç spor yapmadığı iki gün vardır.'], 'Yüzme ve koşu günleri ayrı olduğundan en az 3 + 3 = 6 gün spor yapılmıştır. Yedi günlük haftada spor yapılmayan gün en çok bir tanedir.'),
  ('Bir koşuda Ece dördüncü sırada bitirmiştir. Ece\'nin geride bıraktığı yarışmacı sayısı, kendisinden önce bitirenlerin sayısının iki katıdır. Koşuya kaç kişi katılmıştır?', '10', ['9', '8', '12'], 'Ece\'den önce 3 kişi vardır; arkasında bunun iki katı 6 kişi kalır. Ece ile birlikte 3 + 1 + 6 = 10 kişi olur.'),
  ('Bir duvar saati her gün tam 10 dakika ileri gitmektedir ve kadranında 12 saat vardır. Bugün doğru saate ayarlanan bu saat, en az kaç gün sonra yeniden doğru saati gösterir?', '72', ['60', '36', '144'], 'Saatin yeniden doğru görünmesi için toplam 12 saat, yani 720 dakika ileri gitmesi gerekir. 720 ÷ 10 = 72 gün.'),
  ('Kemal\'in tek kız kardeşinin tek kızı Melis\'tir. Melis\'in babası Kemal\'in nesidir?', 'Eniştesi', ['Kayınbiraderi', 'Bacanağı', 'Amcası'], 'Melis\'in babası, Kemal\'in kız kardeşinin eşidir. Kız kardeşin eşine enişte denir.'),
  ('“Kâğıt : ağaç” ilişkisine göre “cam : ?” ikilisinde soru işaretinin yerine hangisi gelmelidir?', 'Kum', ['Pencere', 'Şişe', 'Ayna'], 'Kâğıt ağaçtan elde edilen bir üründür; cam da kumdan elde edilir. Pencere, şişe ve ayna camdan yapılan ürünlerdir.'),
  ('“Hiç kimse her zaman haklı değildir.” önermesiyle çelişen önerme hangisidir?', 'Her zaman haklı olan biri vardır.', ['Bazı kişiler bazen haksızdır.', 'Herkes bazen haklıdır.', 'Kimse hiçbir zaman haklı değildir.'], 'Önerme, her zaman haklı olan bir kişinin bulunmadığını söyler. Çelişiği, böyle en az bir kişinin bulunmasıdır.'),
  ('Bir sınıfta 12 kız ve 10 erkek öğrenci vardır. Bu öğrencilerden 15\'i bir geziye katılmıştır. Buna göre hangisi kesinlikle doğrudur?', 'En az beş kız öğrenci gezidedir.', ['En az altı erkek öğrenci gezidedir.', 'Gezide tam olarak yedi kız öğrenci vardır.', 'Gezide hiç erkek öğrenci bulunmamaktadır.'], 'Geziye en çok 10 erkek katılabilir; kalan en az 5 kişi kızdır. Erkeklerin en az 3 olduğu da kesindir ama 6 olması gerekmez.'),
  ('Bir dolapta 6 gömlek vardır; bunların 4\'ü beyaz, 3\'ü uzun kolludur. Buna göre hangisi kesinlikle doğrudur?', 'En az bir beyaz gömlek uzun kolludur.', ['Her uzun kollu gömlek beyazdır.', 'Tam olarak iki beyaz gömlek kısa kolludur.', 'Beyaz olmayan her gömlek kısa kolludur.'], 'Beyaz ve uzun kollu gömleklerin toplamı 4 + 3 = 7\'dir ve bu sayı 6\'yı bir aşar. Aşan kısım iki özelliği birlikte taşıyan en az bir gömleğe karşılık gelir.'),
  ('“Tuğla : duvar” ilişkisine göre “? : kolye” ikilisinde soru işaretinin yerine hangisi gelmelidir?', 'Boncuk', ['Kuyumcu', 'Boyun', 'Altın rengi'], 'Tuğlalar bir araya gelerek duvarı oluşturur; boncuklar da dizilerek kolyeyi oluşturur. Bu bir parça-bütün ilişkisidir.'),
];
